/* AYT matematik 241–349: özgün grafik ve metin üzerinden bireysel çözümler. */
(() => {
 const all=window.EXAM_ANALYSES=window.EXAM_ANALYSES||{};
 function add(n,title,topic,book,page,tests,knowledge,reasoning,trap,concept,why,stem,options,answer,explanation,resolvedAnswer){
  all[`q-ayt-matematik-${String(n).padStart(3,'0')}`]={title,topic,lessonIds:[],studyRefs:[{book,page,title:topic}],tests,knowledge,reasoning,trap,connections:[{concept,why}],variation:{stem,options,answer,explanation},status:'reviewed',keyCheck:'matches',resolvedAnswer,note:''};
 }
 add(241,'Yükseklikten dikdörtgen genişliğini kurma','Maksimum–minimum','AYT-mat',87,
 'Aynı yükseklikte iki doğru üzerindeki köşelerin apsis farkını dikdörtgen genişliği yapıp alanı tek değişkenli parabol olarak maksimize etmeyi ölçer.',
 ['Yükseklik h için sol köşe apsisi(h−2)/3,sağ köşe apsisi12−h’dir.','Genişlik(38−4h)/3,alan A(h)=h(38−4h)/3 olur;şekil koşulları h≥2 gerektirir.'],
 ['A′=(38−8h)/3=0’dan h=19/4 bul;negatif ikinci türev maksimumu doğrular.','Genişlik(38−19)/3=19/3’tür. Doğru seçenek B’dir;istenen maksimum alanın kendisi değil,x ekseni üzerindeki kenardır.'],
 '12−h değerini tek başına genişlik sanmak sol köşenin orijinde sabit olmadığını unutur;iki apsis çıkarılmalıdır.',
 'Analitik modelleme','Grafik koşulları yatay kenar uzunluğuna dönüşür;iki doğrusal sınırın farkı alanı ikinci derece yapar.',
 'A(h)=h(20−2h) alanı maksimumken20−2h genişliği kaçtır?',['5','8','10','12','15'],2,'A′=20−4h=0,h=5 olur. Genişlik20−10=10’dur.','B');
 add(242,'Türevli özdeşlikte derece ve baş katsayı','Polinom türevi','AYT-mat',78,
 '[(f(x))³]′=(f′(x))⁴ eşitliğinde önce polinom derecelerini,ardından baş katsayıları eşitleyerek a·n değerini bulmayı ölçer.',
 ['Sol derece3n−1,sağ derece4(n−1)’dir;n pozitif olduğundan f′ sıfır polinomu değildir.','Derece eşitliği3n−1=4n−4 ile n=3 verir.'],
 ['Sol baş katsayı3a²·an=3na³=9a³,sağdaki(an)⁴=81a⁴’tür.','a≠0 olduğundan9=81a,a=1/9 bulunur. a·n=1/3,cevap B’dir.'],
 'Sol tarafı f′(x)³ sanmak küpün türevindeki3f²f′ çarpımını kaybeder;köşeli parantezin dışındaki türev bütün küpe uygulanır.',
 'Derece analizi','Özdeşliği tamamen açmadan en yüksek terimler hem dereceyi hem ölçeği belirler;düşük dereceli katsayılara gerek yoktur.',
 'Derecesi4 olan P için(P³)′ derecesi kaçtır?',['8','9','10','11','12'],3,'P³ derecesi12’dir;türev dereceyi bir azaltır. Sonuç11 olur.','B');
 add(243,'İki teğetten bileşke çarpım türevi','Çarpım ve zincir kuralı','AYT-mat',80,
 'Teğet doğrularından f(2),f′(2),f(5),f′(5) değerlerini çıkarıp x²f(f(x)) türevinde doğru noktalara yerleştirmeyi ölçer.',
 ['y=3x−1 teğeti f(2)=5,f′(2)=3 verir.','y=2x+4 teğeti f(5)=14,f′(5)=2 verir;ilk çıktı5 olduğu için ikinci teğet bilgisi kullanılır.'],
 ['g′=2xf(f(x))+x²f′(f(x))f′(x) yaz.','x=2 için4·14+4·2·3=56+24=80 bulunur. Doğru seçenek C’dir;çarpım ve zincir kuralları birlikte gereklidir.'],
 'f′(f(2)) yerine f′(2) kullanmak iç fonksiyonun girdiyi5’e taşıdığını kaçırır;iki farklı türev değeri çarpılır.',
 'Teğetten fonksiyon bilgisi','Doğru eğimi türevi,teğet noktasındaki doğru değeri fonksiyon çıktısını verir;aynı grafik bilgisi iki biçimde değerlendirilir.',
 'f(2)=5,f(5)=14,f′(2)=3,f′(5)=2 ise(f∘f)′(2) kaçtır?',['3','5','6','14','42'],2,'Zincir kuralıyla f′(f(2))f′(2)=f′(5)·3=2·3=6’dır.','C');
 add(244,'Sabit türevlerde minimumun derinliği','Türev ve net değişim','AYT-mat',81,
 '−2 ve3 sabit türev parçalarından f’nin V biçiminde azalıp arttığını çıkarıp5 ve20 kökleri arasında minimum apsisini belirlemeyi ölçer.',
 ['Türev işaretinin−2’den3’e geçtiği t noktasında f yerel minimum alır.','5’ten t’ye değer değişimi−2(t−5),t’den20’ye değişim3(20−t)’dir.'],
 ['İki uçta f=0 olduğundan−2(t−5)+3(20−t)=0,t=14 bulunur.','Minimum f(14)=−2·9=−18’dir. Doğru seçenek A’dır;grafikteki−2 minimum fonksiyon değeri değilazalma eğimidir.'],
 'Türev grafiğinin en alt y değerini f’nin minimumu sanmak fonksiyon iletürevin değerlerini karıştırır;minimuma ulaşmak için değişim biriktirilir.',
 'İşaret değişimi','Türevin negatiften pozitife geçişi minimumu konumlandırır;iki sabit eğimde doğrusal değişimler minimum seviyesini hesaplatır.',
 'f(5)=0 ve5–14 aralığında f′=−2 ise f(14) kaçtır?',['−20','−18','−16','−12','−9'],1,'Dokuz birimlik aralıkta değişim−2·9=−18’dir. Başlangıç0 olduğundan f(14)=−18 bulunur.','A');
 add(245,'Verilen değer ve türevden ikinci türev','Polinom türevi','AYT-mat',78,
 'f=x²(ax+b) çarpımını ax³+bx² yapıp f(1) ve f′(2) koşullarından iki katsayıyı belirlemeyi ölçer.',
 ['f(1)=a+b=1’dir.','f′=3ax²+2bx olduğundan f′(2)=12a+4b=2, yani3a+b=1/2 olur.'],
 ['İki eşitliği çıkararak2a=−1/2,a=−1/4 ve b=5/4 bul.','f″(3)=6a·3+2b=−18/4+10/4=−2’dir. Doğru seçenek B’dir;istenen ikinci türevdir.'],
 'f′(2)=2 bilgisini f(2)=2 gibi kullanmak katsayı sistemini tamamen değiştirir;türev işareti dikkatle izlenmelidir.',
 'Doğrusal parametre sistemi','Polinomun farklı nokta ve türev değerleri katsayılar için doğrusal denklemler verir;ikinci türev sonra doğrudan hesaplanır.',
 'f(x)=ax³+bx², f(1)=2 ve f′(1)=5 ise f″(2) kaçtır?',['8','10','12','14','16'],3,'a+b=2 ve 3a+2b=5 denklemleri a=b=1 verir. İkinci türev 6ax+2b olduğundan f″(2)=12+2=14 bulunur.','B');
 add(246,'Üst konumundaki3 ile anahtar çatışması','Türevde kaynak verisi denetimi','AYT-mat',79,
 'Toplam ve çarpım türevini ölçmeyi amaçlar;ancak büyütülmüş kaynakta f=x^(a+3) yazılması pozitif tam sayı a koşuluyla çelişmektedir.',
 ['Basılan f=x^(a+3) için f′(1)=a+3;g=√x+ax için g′(1)=1/2+a’dır.','Toplam türev9/2 koşulu2a+7/2=9/2,a=1/2 verir;bu değer pozitif tam sayı değildir.'],
 ['Dolayısıyla soru basıldığı haliyle uygun a üretmez ve anahtar A doğrudan doğrulanamaz.','Olası amaçlanan f=x^a+3 alınırsa a=2,f(1)=4,f′(1)=2,g(1)=3,g′(1)=5/2 ve çarpım türevi16 çıkar;anahtar A bu farklı gösterimle uyumludur.'],
 'Anahtara ulaşmak için üstteki+3’ü açıklamasız tabana indirmek kaynak metnini sessizce değiştirmektir;iki okuma açıkça ayrılmalıdır.',
 'Gösterim ve işlem sırası','x^(a+3) ilex^a+3 farklı fonksiyonlardır;bir üst konumu hatası hem parametreyi hem çarpım türevini değiştirir.',
 'f=x²+3,g=√x+2x açıkça verilirse(fg)′(1) kaçtır?',['16','15','14','13','12'],0,'f(1)=4,f′(1)=2,g(1)=3,g′(1)=5/2’dir. Çarpım türevi2·3+4·5/2=16 olur.','A');
 all['q-ayt-matematik-246'].keyCheck='conflict';
 all['q-ayt-matematik-246'].note='Özgün PDF79 büyütülerek kontrol edildi: f(x)=x^(a+3) basılmıştır. Toplam türev koşulu a=1/2 vererek pozitif tam sayı şartıyla çelişir. Anahtar A=16 ancak f=x^a+3 biçiminde farklı bir gösterim kabul edilirse çıkar;olası üst konumu baskı hatasıdır.';
 add(247,'Artan fonksiyon integralinin sınırları','Belirli integral','AYT-mat',95,
 'Sürekli artan f’nin[0,1] ve[1,2] parçalarında uç değer dikdörtgenleri arasında kalmasından integralin5 ile7 arasında olduğunu ölçer.',
 ['0–1 arasında2<f(x)<3,1–2 arasında3<f(x)<4 iç noktalarda geçerlidir.','İntegraller sırasıyla2 ile3 ve3 ile4 arasında kalır;toplam5 ile7 arasındadır.'],
 ['Seçenek4,4,5 ve7,5,8 bu açık aralığın dışındadır.','6 mümkündür;örneğin f(x)=x+2 verileri sağlar ve0–2 integrali6’dır. Doğru seçenek C’dir;yalnız sınır içinde kalmak değilörnekle mümkünlük de gösterilir.'],
 'f(0)+f(1)+f(2)=9’u integral saymak ayrık nokta değerleriyle sürekli alanı karıştırır;aralık uzunluklarıyla sınırlama yapılmalıdır.',
 'Riemann alt–üst toplamları','Artan fonksiyonda sol uç dikdörtgenler alt,sağ uç dikdörtgenler üst sınır sağlar;verilen orta nokta iki dar sınır oluşturur.',
 'f=x+2 ise∫₀²f(x)dx kaçtır?',['4','5','6','7','8'],2,'İlkel fonksiyon x²/2+2x’tir.2’de2+4=6,0’da0 verir.','C');
 add(248,'İşaretli bölgelerde ortak alanın iptali','İntegral ile alan','AYT-mat',98,
 'Üç eğri arasındaki renkli bölgeleri işaretli integral olarak okuyup A₂’nin iki integralde ters katkıyla sadeleştiğini ölçer.',
 ['a–c arasında h,g’nin altında olduğundan∫(h−g)=−A₁−A₂’dir.','b–d arasında f,h’nin üstünde olduğundan∫(f−h)=A₂+A₃ olur.'],
 ['İki katkıyı topla:−A₁−A₂+A₂+A₃=A₃−A₁.','Verilen alanlarla9−1=8 bulunur. Doğru seçenek B’dir;mor3 birimlik bölge iki kez pozitif sayılmaz.'],
 'Boyalı alanların hepsini1+3+9 diye toplamak integrandaki sıra ve işaretleri atlar;belirli integral geometrik alanın mutlak değeri değildir.',
 'Toplanabilirlik ve iptal','Aynı bölge bir integraldealt−üst,diğerindeüst−alt olarak yer aldığında işaretli katkıları birbirini giderir.',
 'I₁=−A₁−A₂,I₂=A₂+A₃ ve alanlar2,5,11 ise I₁+I₂ kaçtır?',['4','6','8','9','18'],3,'A₂ iptal olur;A₃−A₁=11−2=9 bulunur.','B');
 add(249,'Parabol altını üçgen ve kalan bölgeye ayırma','İntegral ile alan','AYT-mat',98,
 'Parabolun altındaki pozitif alanı(0,b),(2,0) doğrusunun oluşturduğu üçgenle karşılaştırıp büyük bölgenin üç kat koşulunu kurmayı ölçer.',
 ['Doğru altında üçgen alanı½·2·b=b’dir.','Parabol altı∫₀²(ax²+b)dx=8a/3+2b;üstte kalan bölge8a/3+b’dir.'],
 ['a,b>0 olduğundan kalan bölge üçgenden büyüktür;oran3 ise8a/3+b=3b yazılır.','8a/3=2b,a/b=3/4 bulunur. Doğru seçenek C’dir;oranın büyük/küçük yönünü pozitiflik belirler.'],
 'Bütün parabol alanını üç katb saymak alan oranının iki parçanın kendi aralarında verildiğini kaçırır;bütün dörtb olmalıdır.',
 'Alan farkı','Eğri altındaki alan iledoğru altındaki üçgen farkı,ayırıcı doğrunun üstündeki ikinci parçayı verir.',
 'Üçgen alanıb,kalan alan3b ise bütün alan kaçb’dir?',['2','3','4','5','6'],2,'İki parça ayrık olup bütünü oluşturur;b+3b=4b olur.','C');
 add(250,'Kesişimde alan integrandının yön değiştirmesi','İntegral ile alan','AYT-mat',98,
 '0–4 aralığında f’nin,4–6 aralığında doğrunun üstte olduğunu grafikten okuyup mutlak alanı iki ayrı farkla hesaplamayı ölçer.',
 ['∫₀⁴x/2 dx=4;bu aralıkta alan8−4=4’tür.','∫₄⁶x/2 dx=(36−16)/4=5;bu aralıkta doğru üstte olduğundan alan5−3=2 olur.'],
 ['İki geometrik katkıyı4+2 olarak topla.','Sonuç6 birimkare,cevap D’dir;tek∫₀⁶(f−x/2) hesabı4−2=2 net alanını verir,istenen toplam alanı vermez.'],
 'Kesişim4’te fark sırasını değiştirmemek sağ bölgenin alanını negatif saydırır;toplam alan için üst−alt her parçada ayrı seçilir.',
 'İşaretli integral ve alan','Net integral zıt taraftaki bölgeleri çıkarır;geometrik toplamda her bölgenin pozitif büyüklüğü alınır.',
 'İki eğri arası işaretli fark alanları+4 ve−2 ise geometrik toplam kaçtır?',['2','4','6','8','−2'],2,'Geometrik toplam|4|+|−2|=6’dır. İşaretli net integral ise2 olur.','D');
 add(251,'Değişken dönüşümüyle dikdörtgen farkı','Belirli integral','AYT-mat',95,
 'f(2x) integralinde sınırları2 ve8’e taşıyıp mavi−sarı net alanını∫(f−c)=2 olarak kullanmayı ölçer.',
 ['u=2x için dx=du/2;∫₁⁴f(2x)dx=½∫₂⁸f(u)du olur.','Verilen28 değeri∫₂⁸f=56 verir;mavi eksi sarı alan2’dir.'],
 ['∫₂⁸(f−c)=56−6c=2 denklemini kur.','6c=54,c=9 bulunur. Doğru seçenek B’dir;değişken değişiminde yalnız sınırları değil1/2 çarpanını da taşımak gerekir.'],
 'İlk integralden∫₂⁸f=28 demek dx dönüşümünü atlar ve c’yi yanlış yarıya indirir.',
 'Net alan ve sabit fonksiyon','y=c doğrusu altındaki dikdörtgen6c alanlıdır;f altı alanın bundan farkı renklerin işaretli farkını verir.',
 '∫₁⁴f(2x)dx=10 ise∫₂⁸f(u)du kaçtır?',['5','10','15','20','40'],3,'Dönüşüm ilk integrali ikincinin yarısı yapar. İkinci integral2·10=20’dir.','B');
 add(252,'Üçgen içindeki eğri alanını iki parçaya ayırma','İntegral ile alan','AYT-mat',97,
 'A₁’in yalnız0–1’de x^a altı değil,1–2’de doğrunun altındaki küçük üçgeni deiçerdiğini görüp alan oranından a’yı bulmayı ölçer.',
 ['Bütün dik üçgen alanı½·2·2=2;A₂=2A₁ olduğundan A₁=2/3’tür.','A₁=∫₀¹x^a dx+½=1/(a+1)+1/2 biçimindedir.'],
 ['1/(a+1)+1/2=2/3 eşitliği1/(a+1)=1/6 verir.','a=5 bulunur;doğru seçenek D’dir. Pozitif tam a koşulu hem integral formülünü hem şeklin artan eğrisini sağlar.'],
 'A₁’i yalnız1/(a+1) saymak kesişim(1,1)’den sağdaki taban1,yükseklik1 üçgenini kaybeder.',
 'Bölgeyi yatay aralıklara ayırma','Üst sınır0–1’de eğri,1–2’de doğru olduğu için tek integral yerineiki farklı parça gerekir.',
 '1/(a+1)=1/6 ve a pozitif tam ise a kaçtır?',['2','3','4','5','6'],3,'Pozitif paydalarda eşitlik a+1=6 verir. Buradan a=5 bulunur.','D');
 add(253,'Parçalı sabit türevde değer aralığı','Türev ve net değişim','AYT-mat',95,
 'Türev grafiğinin üç sabit parçasını uzunluklarıyla çarparak toplam değişimi c’ye bağlı bulup0<c<2 koşulundan f(6) aralığını ölçer.',
 ['0–3 katkısı2·3=6,3–4 katkısı−3·1=−3,4–6 katkısı2c’dir.','Süreklilik parçalar arası değerleri bağlar;toplam değişim6−3+2c=3+2c olur.'],
 ['f(0)=5 eklenince f(6)=8+2c elde edilir.','0<c<2 nedeniyle8<f(6)<12’dir. Seçeneklerden yalnız10,1 bu aralıktadır;cevap C’dir.'],
 'c’nin kendisini f(6) saymak grafiğin türev grafiği olduğunu unutur;f değerine geçmek içinalan ve başlangıç değeri gerekir.',
 'Belirli integralin temel teoremi','f(6)−f(0)=∫₀⁶f′ ifadesi türev alanını net değişime çevirir;negatif dikdörtgen çıkarılır.',
 'f(6)=8+2c ve0<c<2 ise hangisi olabilir?',['7,5','8','9','12','13'],2,'Olası aralık(8,12)’dir.9 için c=1/2 seçilebilir;uçlar dahil değildir.','C');
 add(254,'Karekökün türeviyle ikame','Belirsiz integral','AYT-mat',90,
 '(3√x+2)⁵/√x integralinde paydadaki1/√x’in iç fonksiyon türeviyle orantılı olduğunu görüp u ikamesi yapmayı ölçer.',
 ['u=3√x+2 seçilirse du=3dx/(2√x) olur.','Bu yüzden dx/√x=(2/3)du ve integral(2/3)∫u⁵du biçimine dönüşür.'],
 ['Kuvvet kuralıyla(2/3)·u⁶/6=u⁶/9 bulunur.','Sonuç(3√x+2)⁶/9+C,cevap B’dir. Türev kontrolünde6·3/(2√x) çarpanı1/9 ilebirlikte özgün integrandı verir.'],
 'İkame sonrası2/3 çarpanını ters almak1/18 gibi yanlış katsayı üretir;du eşitliği dx/√x için açıkça çözülmelidir.',
 'Zincir kuralının tersi','Bileşke kuvvetin ilkelini alırken iç fonksiyon türevini dengeleyen sabit dışarı çıkarılır.',
 'u=3√x+2 ise dx/√x hangi ifadeye eşittir?',['du/3','du/2','2du/3','3du/2','3du'],2,'du=(3/2)dx/√x olduğundan her iki taraf2/3 ile çarpılır;dx/√x=(2/3)du olur.','B');
 add(255,'Türev alanlarını biriktirerek kök sayma','Türev ve integral','AYT-mat',95,
 'f′ grafiğinin her lobunda f’nin monotonluğunu kullanıp başlangıç−1/2’den itibaren alanları işaretli toplayarak sıfır geçişlerini saymayı ölçer.',
 ['Lob sonlarındaki f değerleri sırasıyla−1/2,5/2,1/2,5/2,−3/2,7/2 olur.','Pozitif f′ lobunda f artar,negatif lobda azalır;her lobda en fazla bir sıfır geçişi vardır.'],
 ['İlk lob−1/2’den5/2’ye, dördüncü5/2’den−3/2’ye,beşinci−3/2’den7/2’ye geçer ve birer kök verir.','İkinci veüçüncü lob uçları pozitiftir ve monotondur,kök vermez. Toplam3 kök,cevap C’dir.'],
 'f′’nin x ekseni kesişimlerini f’nin kökü saymak kritik noktalarla fonksiyon sıfırlarını karıştırır;kümülatif değerler izlenmelidir.',
 'Ara değer ve monotonluk','Zıt işaretli uçlar en az bir kökü,tek yönlü değişim en fazla bir kökü garanti eder;birlikte tam kök sayısı verir.',
 'Sürekli ve kesin artan f,aralık uçlarında−2 ve3 değerlerini alıyorsa kaç kökü vardır?',['0','1','2','3','Belirlenemez'],1,'Ara değer teoremi en az bir kök sağlar;kesin artanlık iki farklı sıfıra izin vermez. Tam bir kök vardır.','C');
 add(256,'Ortak integral aralığını iptal etme','Belirli integral ve süreklilik','AYT-mat',96,
 'İki integralin2–4 ortak kısmını çıkararak0–2 ve4–6 parçalarını eşitlemeyi ve2’deki süreklilikle b=2a koşulunu kullanmayı ölçer.',
 ['2’de sol parça6−3·4/2=0 olduğundan2a−b=0,b=2a’dır.','Verilen eşitlik∫₀²f=∫₄⁶f biçimine sadeleşir;ortak2–4 alanı iki taraftan çıkarılır.'],
 ['Sol integral[6x−x³/2]₀²=8’dir. Sağ integral10a−2b=6a olur.','a=4/3,b=8/3 ve a+b=4 bulunur. Doğru seçenek D’dir.'],
 'Her iki integrali bütün parçalarıyla açmak mümkündür ama ortak aralığı iptal etmemek gereksiz hesap üretir;önce sınır yapısı kullanılmalıdır.',
 'İntegral toplamsallığı','Bir aralık integrali bitişik alt aralıkların toplamıdır;eşitlikte aynı alt integral tıpkı cebirsel ortak terim gibi giderilebilir.',
 '∫₀⁴f=∫₂⁶f ise hangi eşitlik zorunludur?',['∫₀²f=∫₄⁶f','∫₀²f=0','∫₂⁴f=0','f(2)=f(4)','f sabittir'],0,'İki taraftan ortak∫₂⁴f çıkarılınca kalanlar∫₀²f ve∫₄⁶f olur.','D');
 add(257,'Boyanmış bölgenin alt sınırının değişmesi','İki eğri arası alan','AYT-mat',98,
 'Parabollerin0 ve3’te kesiştiğini,x ekseninin2’ye kadar alt sınır olup sonra f’nin alt sınırı devraldığını grafikten okuyarak alanı ölçer.',
 ['f=g denklemi2x(x−3)=0 verir;pozitif kesişim3’tür.','0–2 arasında boyalı alan g ilex ekseni arasında;2–3 arasında g ilef arasındadır.'],
 ['∫₀²g=16/3 hesapla.∫₂³(g−f)=∫₂³(−2x²+6x)=7/3 bulunur.','Toplam23/3 birimkare,cevap E’dir;0–2’de f’nin eksen altındaki çukuru boyalı alana dahil değildir.'],
 '0–3 boyunca g−f almak f’nin negatif kısmını daüstteki alana ekler;şekilde sınır0–2’de x eksenidir.',
 'Parçalı alan modeli','Boyanın gerçek sınırı integralin alt fonksiyonunu belirler;fonksiyonların kesişimleri tek başına yeterli değildir,eksen kesişimleri deizlenir.',
 'g=−x²+4x için∫₀²g kaçtır?',['8/3','4','14/3','16/3','6'],3,'[−x³/3+2x²]₀²=−8/3+8=16/3 bulunur.','E');
 add(258,'Parametreli polinom integralinden a','Belirli integral','AYT-mat',95,
 '3x²+2ax+a ifadesini x’e göre integre ederken a’yı sabit tutup1 ve3 sınırları arasındaki farktan doğrusal parametre denklemi kurmayı ölçer.',
 ['İlkel fonksiyon x³+ax²+ax’tir;a parametresi x’e göre sabittir.','3 ve1 arasında x³ katkısı27−1=26,diğer iki katkıa(9−1)+a(3−1)=10a olur.'],
 ['26+10a=56 denklemini kur.','10a=30,a=3 bulunur. Doğru seçenek A’dır;belirli integralde eklenen keyfî sabit sınır farkında zaten yok olur.'],
 '2ax’in integralini ax almak x kuvvetinin bir artması kuralını ihlal eder;doğrusu ax²’dir.',
 'Parametrede doğrusal yapı','İntegral işlemi toplama ve sabit çarpanlar üzerinde doğrusaldır;bilinmeyen a integral sonrasında da birinci derecede kalır.',
 '∫₁³2ax dx hangi ifadeye eşittir?',['2a','4a','6a','8a','10a'],3,'İlkel ax²’dir. Sınır farkıa(9−1)=8a olur.','A');
 add(259,'Doğru–parabol alanının m küpüne bağlılığı','İntegral ile alan','AYT-mat',98,
 'mx ilex² kesişiminin x=m olduğunu bulup bütün alanı m³/6;2x’in ayırdığı küçük alanı4/3 olarak hesaplamayı ölçer.',
 ['mx=x² kökleri0,m;üstte doğru olduğundan bütün alan∫₀^m(mx−x²)dx=m³/6’dır.','Küçük A₂ alanı2x ilex² arasında0–2’de kalır;∫₀²(2x−x²)dx=4/3’tür.'],
 ['A₁=7A₂ olduğundan bütün alan8A₂=32/3 olur.','m³/6=32/3,m³=64 ve m=4 bulunur. Doğru seçenek B’dir;şekilde m>2 yönü sonuçla uyumludur.'],
 'Bütün alanı7A₂ kabul etmek A₁’in yedi kat olduğunu ama iki parçanın toplamının sekiz kat olduğunu kaçırır.',
 'Ölçek yasası','Doğrunun eğimi m artınca kesişim apsisi m,değer ölçeği m² olur;alanın m³ ileartması integralde görülür.',
 'y=mx iley=x² arasındaki alan m³/6 ise m=4 için alan kaçtır?',['8/3','16/3','32/3','64/3','32'],2,'4³/6=64/6=32/3 birimkaredir.','B');
 add(260,'x²−2 ikamesi ve işaretli alan','Belirli integral','AYT-mat',90,
 '∫₀²x f(x²−2)dx integralinde u=x²−2 seçerek−2–2 aralığındaki toplam işaretli alanı bulmayı veeksik bölgeyi hesaplamayı ölçer.',
 ['du=2x dx olduğundan verilen integral½∫_−2²f(u)du=9 olur.','Bu yüzden toplam işaretli integral18’dir;mavi5,kırmızı6 pozitif,sarı1 negatif katkı verir.'],
 ['Eksik S=∫_−1⁰f için5+S+6−1=18 yaz.','S=8 bulunur. Doğru seçenek B’dir;ikameyi x−2 sanmak sınırları ve1/2 çarpanını yanlış kurar.'],
 'Sarı alanı+1 eklemek x ekseni altındaki f’nin integrale negatif katkı verdiğini unutur;geometrik alanın büyüklüğü1 olsa da işaret−1’dir.',
 'İkame ve net alan','İç fonksiyonun türevi dıştaki x ileorantılıdır;dönüşüm sonrası soru bilinen Venn benzeri alan parçalarını toplama problemine iner.',
 '5+S+6−1=18 ise S kaçtır?',['6','7','8','9','10'],2,'Bilinen işaretli katkılar10 eder. S=18−10=8 bulunur.','B');
 add(261,'Artan fonksiyonda üst ve alt dikdörtgenler','Belirli integral','AYT-mat',92,
 'Pozitif artan grafiğin alanını sağ uç yükseklikli üst toplamlarla,sol uç yükseklikli alt toplamdan ayırmayı ölçer.',
 ['Tek6 genişlikli sağ uç dikdörtgen alanı6f(6),grafiği yukarıdan örter.','İki3 genişlikli sağ uç dikdörtgen3f(3)+3f(6) deüst sınırdır;üç2 genişlikli sol uç toplamı ise alt sınırdır.'],
 ['Alan I veII değerlerinden küçüktür. III=2f(0)+2f(2)+2f(4) grafiğin altında kaldığından alan ondan büyüktür.','Doğru seçenek C’dir;süreklilik ve artış bu çizimde dikdörtgen farklarının pozitif olmasını sağlar.'],
 'Bütün dikdörtgen toplamlarını aynı yönde sınır sanmak seçilen uçları gözden kaçırır;artan fonksiyonda sağ uç üst,sol uç alt toplam verir.',
 'Riemann toplamları','Alt ve üst toplamlar alanı çevreler;aralığı inceltmek kesin alanı bilmeden karşılaştırma yapmayı sağlar.',
 'Artan f için[0,2] aralığında2f(0) alanın hangi sınırıdır?',['Üst','Alt','Her zaman eşit','Negatif','Sınır değildir'],1,'Sol uç değeri bütün aralıktaki f değerlerinden küçük olduğundan2f(0) alt dikdörtgen toplamıdır.','C');
 add(262,'Küpkök içinin türeviyle ikame','Belirli integral','AYT-mat',90,
 '(x+2)∛(x²+4x−4) integralinde iç polinom türevinin2(x+2) olduğunu kullanıp yeni sınırları1 ve8 olarak hesaplamayı ölçer.',
 ['u=x²+4x−4,du=2(x+2)dx olur.','x=1 için u=1,x=2 için u=8’dir;integral½∫₁⁸u^(1/3)du biçimine dönüşür.'],
 ['İlkel½·(3/4)u^(4/3)=3u^(4/3)/8 olur.','Sınır farkı3(16−1)/8=45/8’dir. Doğru seçenek A’dır;8^(4/3)=16 hesaplanır.'],
 'Küpkökü karekök sanmak kuvveti1/2 aldırır;özgün kök göstergesindeki3 korunmalıdır.',
 'Zincir kuralının tersi','Dıştaki x+2 tam olarak iç türevin yarısıdır;ikameyle polinom–kök çarpımı basit kuvvet integraline iner.',
 '∫₀³(x+1)√(x²+2x+1) dx kaçtır?',['7','14','21','28','42'],2,'u=x²+2x+1 seçilirse du=2(x+1)dx, yeni sınırlar 1 ve 16 olur. İntegral (1/2)∫₁¹⁶√u du=(64−1)/3=21’dir. İç türev çarpanı burada da yarım katsayısını gerektirir.','A');
 add(263,'Mutlak alan ve net integralden negatif bölge','İntegral ile alan','AYT-mat',97,
 '∫|f|=20 ve∫f=8 verilerini pozitif alan P,negatif alan büyüklüğü N ile iki denklem yapıp ölçekli integrali bulmayı ölçer.',
 ['Grafikte a–b arasında f negatif,b–c arasında pozitiftir.','P+N=20 ve P−N=8 olduğundan2N=12,N=6 olur.'],
 ['∫_a^bf=−6’dır. u=2x ikamesi istenen integralin½∫_a^bf olmasını sağlar.','Sonuç−3,cevap A’dır;hem negatif bölgenin işareti hem1/2 ölçeği korunur.'],
 '20−8=12’yi doğrudan negatif alan sanmak farkın negatif bölgeyi iki kez saydığını kaçırır;önce ikiye bölünmelidir.',
 'Toplam ve fark','Geometrik toplam ileişaretli net toplam,iki bilinmeyen alanı ayrı ayrı belirler;ikame ardından yatay ölçeği değiştirir.',
 'P+N=30,P−N=10 ise negatif alan büyüklüğü N kaçtır?',['5','10','15','20','25'],1,'İki eşitlik çıkarılınca2N=20,N=10 bulunur. Negatif integral katkısı−10’dur.','A');
 add(264,'Karekök altında iki farklı alan','İntegral ile alan','AYT-mat',98,
 'Mavi bölgenin0–9 arasında iki eğri farkı,sarı bölgenin4–9 arasında√x iley=2 farkı olduğunu okuyup alan çarpımından a’yı bulmayı ölçer.',
 ['A₁=(a−1)∫₀⁹√x dx=18(a−1)’dir.','Sarı bölge x=4’te√x=2’den başlar;A₂=∫₄⁹(√x−2)dx=8/3 olur.'],
 ['A₁A₂=18(a−1)·8/3=48(a−1)=96 yaz.','a−1=2,a=3 bulunur. Doğru seçenek B’dir;grafikte a>1 olması mavi farkın pozitifliğini sağlar.'],
 'Sarı alanı0–9 arasında√x−2 integrali almak x<4 kısmındaki boyanmamış negatif bölgeyi dehesaba katar.',
 'Kesişim sınırı','Alan integrali şeklin başladığı gerçek kesişim apsisinden alınır;√x=2 koşulu4 sınırını verir.',
 'a>1 iken y=a√x ile y=√x arasında 0≤x≤4 bölgesinin alanı 8 ise a kaçtır?',['1','3/2','2','5/2','3'],3,'Alan (a−1)∫₀⁴√x dx=(a−1)·16/3 olur. Bunu 8’e eşitleyince a−1=3/2, a=5/2 bulunur.','B');
 add(265,'Türev integralinden uzak nokta değeri','İntegralin temel teoremi','AYT-mat',96,
 '∫f′(3x) dönüşümünde1/3 çarpanını kullanıp f(6)’yı,f(2x) ilkelinin türevinden g′(3)’ü bulmayı ölçer.',
 ['∫₁²f′(3x)dx=[f(6)−f(3)]/3=4’tür.','∫f(2x)dx=g(x)+C eşitliği türevlenince g′(x)=f(2x) olur.'],
 ['f(3)=5 olduğundan f(6)−5=12,f(6)=17 bul.','g′(3)=f(6)=17’dir;doğru seçenek E’dir. İkinci eşitlikte yeniden2 çarpanı eklenmez;integral türevlenince integrand aynen geri gelir.'],
 'g′=2f′(2x) yazmak g’yi f(2x) ilekarıştırır;g burada bu ifadenin ilkel fonksiyonudur.',
 'Türev–integral tersliği','İlk integral değer farkını,ikinci belirsiz integral g’nin türevini belirler;iki ters işlem aynı noktada bağlanır.',
 '∫₁²f′(3x)dx=2 ve f(3)=4 ise f(6) kaçtır?',['6','8','10','12','14'],2,'İçteki 3x nedeniyle ilkel fonksiyon f(3x)/3’tür. [f(6)−4]/3=2 olduğundan iki uç değerin farkı 6, f(6)=10 bulunur.','E');
 add(266,'Parametre karekökünü ayırma','Belirli integral','AYT-mat',95,
 'a√x+x√a integralinde x’e bağlı ve parametreye bağlı kökleri ayırıp pozitif a sayesinde√a’ya bölmeyi ölçer.',
 ['∫₁⁴a√x dx=14a/3’tür.','∫₁⁴x√a dx=15√a/2’dir;√a,x’e göre sabit çarpandır.'],
 ['14a/3+15√a/2=59a/3 eşitliğinden15√a/2=15a elde et.','a>0 için√a=1/2,a=1/4 bulunur. Doğru seçenek A’dır;a=0 açıkça yasaktır.'],
 'x√a’yı√(ax) sanmak kök çizgisinin kapsamını değiştirir;bu terimde yalnız a kökün içindedir.',
 'Parametreyi sabit tutma','İntegral x’e göre alındığında a ve√a katsayıdır;sonuçta a ile√a arasında cebirsel denklem kalır.',
 'a>0 için ∫₀¹(a+x√a) dx=3a ise a kaçtır?',['1/16','1/9','1/4','1/2','1'],0,'İntegral a+√a/2 verir. Eşitlikten √a=4a çıkar. a pozitif olduğundan √a’ya bölünür: 1=4√a, sonuç a=1/16’dır.','A');
 add(267,'İki farklı bileşke integralini ayırma','Belirli integral','AYT-mat',90,
 'f(g(x)) içinde doğrusal g’yi ikameyle,g(f(x)) içinde ise2f(x)+2 açılımıyla kullanarak0–2 integralini bulmayı ölçer.',
 ['İlk eşitlik½∫₀⁴f(u)du=18, yani∫₀⁴f=36 verir.','İkinci eşitlik∫₂⁴(2f(x)+2)dx=18’den2∫₂⁴f+4=18,integral7 çıkar.'],
 ['Bütün0–4 integralinden2–4 parçasını çıkar.','∫₀²f=36−7=29 bulunur. Doğru seçenek D’dir;bileşkelerin yer değiştirmesi aynı integrandı üretmez.'],
 'f∘g ileg∘f’yi eşit saymak iki veriyi aynı koşul sanmaya yol açar;g doğrusal olsa da farklı yerlere uygulanmıştır.',
 'Bileşke sırası','İç doğrusal dönüşüm integral sınırlarını değiştirir;dış doğrusal dönüşüm integrandı katsayı ve sabitle açar.',
 'g(x)=2x+2 için g(f(x)) nedir?',['f(2x+2)','2f(x)+2','2f(x+2)','f(x)+4','2f′(x)'],1,'g’nin girdisi f(x) olduğundan kuraldaki x yerine f(x) yazılır:2f(x)+2.','D');
 add(268,'Mutlak integral eşitliğinden alan bağı','İntegral ile alan','AYT-mat',97,
 'Dört alanı A,D pozitif,B,C negatif katkılar olarak yazıp verilen mutlak integral eşitliğinden D=B+2C ilişkisini çıkarmayı ölçer.',
 ['Sol∫|f|=A+B+C+D,ilk sağ integral A−B−C+D’dir.','0–m aralığının iki kat integrali2(D−C)’dir.'],
 ['Eşitlikten A+B+C+D=A−B−3C+3D, yani D=B+2C bulunur.','İstenen net integral A−B−C+D=A+C olur. Doğru seçenek B’dir;alan büyüklükleri ileintegral işaretleri ayrıdır.'],
 'Sağdaki2f integralinde0–m sınırını−m–m sanmak A veB’yi ikinci kez ekler;yalnız sağ yarı alanları kullanılır.',
 'İşaretli bölge denklemleri','Fonksiyonun formülü bilinmeden alan eşitlikleri cebirsel bağıntı üretir;istenen toplam bu bağıntıyla sadeleşir.',
 'D=B+2C ise A−B−C+D nedir?',['A+B','A+C','A+D','B+C','C+D'],1,'D yerineB+2C yazıldığında−B+B ve−C+2C sadeleşerek A+C kalır.','B');
 add(269,'Çarpımı açıp parametreli alanı çözme','Belirli integral','AYT-mat',95,
 '0–1 aralığında(3x+a)(1−x) ifadesini polinom olarak açarak a’nın katsayısını1/2 bulmayı ölçer.',
 ['İntegrand3x−3x²+a−ax biçiminde açılır.','0–1 integral katkıları3/2−1+a−a/2=1/2+a/2 olur.'],
 ['(a+1)/2=17 eşitliğini kur.','a+1=34 ve a=33 bulunur. Doğru seçenek E’dir;çarpım integralinde her çarpanın integralini ayrı çarpma kuralı yoktur.'],
 '∫uv=∫u·∫v varsayımı genel olarak yanlıştır;bu soruda basit çarpım açılımı doğru ve kısa yöntemdir.',
 'İntegralin doğrusallığı','Toplanan polinom terimleri ayrı ayrı integre edilebilir;parametre a,x’e göre sabit kalır ve doğrusal denklem verir.',
 '∫₀¹(2x+b)(1−x) dx=5/6 ise b kaçtır?',['0','1/2','1','3/2','2'],2,'Çarpım açılınca 2x−2x²+b−bx elde edilir. İntegral 1−2/3+b/2=1/3+b/2 olur. 5/6’ya eşitlemek b=1 verir.','E');
 add(270,'Birim aralık integrallerini ikame sonrası toplama','Belirli integral','AYT-mat',96,
 'f(2x) için u=2x değişimiyle−2–2 aralığını dört birim parçaya ayırıp verilen a² kuralını negatif a’larda dauygulamayı ölçer.',
 ['∫_−1¹f(2x)dx=½∫_−2²f(u)du olur.','Dört birim aralığın sol uçları−2,−1,0,1 olduğundan katkılar4,1,0,1’dir.'],
 ['Toplam∫_−2²f=4+1+0+1=6 bulunur.','İstenen bunun yarısı3’tür;doğru seçenek C’dir. Sol uç a negatif olsa da verilen integral değeri a² pozitif olabilir.'],
 'a² kuralını yalnız pozitif tam sayılara uygulamak kaynaktaki her tam sayı ifadesini daraltır;−2 ve−1 aralıkları önemlidir.',
 'Aralık toplamsallığı','Sürekli bir formül bulmadan komşu birim integraller toplanır;ikame aynı bilgiyi farklı genişlikte aralıkta kullanmayı sağlar.',
 '∫_a^(a+1)f=a² ise∫_−2⁰f kaçtır?',['1','2','3','4','5'],4,'−2–−1 katkısı4,−1–0 katkısı1’dir. Toplam5 bulunur.','C');
 add(271,'Aynı dikdörtgenin üç alanını kıyaslama','İntegral ile alan','AYT-mat',98,
 'x√x ve4√x eğrilerinin(4,8) kesişimini bulup32 alanlı dikdörtgende S,M,K bölgelerini kuvvet integralleriyle ayırmayı ölçer.',
 ['S=∫₀⁴x^(3/2)dx=64/5’tir.','Üst eğri altı∫₀⁴4√x dx=64/3;M=64/3−64/5=128/15 olur.'],
 ['K=32−64/3=32/3=160/15 ve S=192/15 yaz.','M=128/15<K=160/15<S=192/15 sırası elde edilir. Doğru seçenek B’dir;alanları yaklaşık gözle kıyaslamak gerekli değildir.'],
 'K’yi doğrudan üst eğri altı alan sanmak kırmızı bölgenin dikdörtgenin bu eğri üstünde kalan parçası olduğunu kaçırır.',
 'Tamamlayıcı bölge','Üst eğri altı M+S,bütün dikdörtgen K+M+S’tir;iki integral ve bir dikdörtgen alanı üç bölgeyi belirler.',
 '128/15,160/15,192/15 alanları hangi sıradadır?',['Birinci>ikinci>üçüncü','İkinci<birinci<üçüncü','Birinci<ikinci<üçüncü','Üçü eşit','Üçüncü<ikinci<birinci'],2,'Ortak pozitif paydada paylar karşılaştırılır;128<160<192 olduğundan sıra değişmez.','B');
 add(272,'Pusula yönlerinden ikizkenar dönüş rotası','Üçgende açı','TYT-mat',114,
 'Kuzey doğrultularını paralel kabul ederek AB doğu,BC güneybatı yönlerini dünya yönlerine çevirip AB=BC ikizkenar koşuluyla dönüş yönünü bulmayı ölçer.',
 ['A’dan B’ye rota kuzeyden90° saat yönünde doğudur;B’den C’ye şekle göre kuzeyden250° yönündedir.','B’de BA yönü270° olduğundan üçgenin tepe açısı20°’dir;taban açıları80° olur.'],
 ['A’dan C’ye yön doğudan80° güneye,yani170°’dir.','Ters C’den A’ya yön350°,kuzeyin10° batısıdır. Bu ayarı gösteren A seçeneği doğrudur;110° kısa açı doğrudan kuzeyden saat yönü kerterizi değildir.'],
 'Her pusula dairesinin üstünü kuzey sanmak şekillerde teknenin yolunun üst yön olarak çizildiğini kaçırır;kuzeyi kırmızı ibre gösterir.',
 'Paralel kuzey doğrultusu','Açı aktarımı için bütün konumlardaki kuzeyler paraleldir;yerel pusula çizimleri ortak bir harita yönüne dönüştürülür.',
 'Bir ikizkenar üçgende eş kenarların arasındaki açı20° ise taban açıları kaçtır?',['70°','75°','80°','85°','90°'],2,'Kalan160° iki eş taban açısına bölünür;her biri80°’dir.','A');
 add(273,'Sabit telde yatay izdüşümün küçülmesi','Pisagor ve paralelkenar alanı','TYT-mat',132,
 '100 alanlı karenin10 birim kenarını koruyup sağ köşelerin6 birim düşmesiyle eğik telin yatay izdüşümünü8 bulmayı ölçer.',
 ['Kare kenarı√100=10’dur;dört telin uzunluğu değişmez.','Eğik üst ve alt telin düşey farkı6 olduğundan yatay uzaklık√(10²−6²)=8 olur.'],
 ['Yeni eşkenar dörtgende sabit düşey kenarı10 taban,yatay8’i yükseklik al.','Alan80’dir;azalma100−80=20 birimkare,cevap B’dir. Düşey kayma6 doğrudan alan yüksekliği olarak alınmaz.'],
 'Yeni alanı10·6=60 hesaplamak düşen köşenin düşey farkını düşey tabana dik yükseklik sanmaktır;yükseklik yatay izdüşümdür.',
 'İzdüşüm ve alan','Bir şeklin alanında yükseklik seçilen tabana dik ölçülür;aynı telin6–8–10 üçgeni bu dik uzaklığı verir.',
 'Hipotenüsü10,düşey bileşeni6 olan doğrunun yatay bileşeni kaçtır?',['4','6','8','10','12'],2,'Pisagor ile yatay²=100−36=64,pozitif uzunluk8 bulunur.','B');
 add(274,'Özdeş yamuk sayısından çerçeve kalınlığı','Yamuk ve alan','TYT-mat',142,
 'Üstte beş,yanlarda üç özdeş ikizkenar yamuğun uzun ve kısa tabanlarını sayarak sabit çerçeve kalınlığını belirlemeyi ölçer.',
 ['Uzun taban L,kısa taban S için üst dış uzunluk3L+2S=26;yan dış uzunluk2L+S=16’dır.','Denklemler L=6,S=4 verir;dik köşedeki eş45° birleşimler nedeniyle L−S=2t ve kalınlık t=1’dir.'],
 ['İç dikdörtgen genişliği26−2=24,yüksekliği16−2=14 cm olur.','Tam görünür resim alanı24·14=336 cm²’dir. Doğru seçenek A’dır;dış416 cm² resim alanı değildir.'],
 'Çerçevenin yalnız dış kenarlarını kullanıp resim alanını416 almak tahta kalınlığını yok sayar;özdeş yamuk sayıları bu kalınlığı buldurur.',
 'Parça sayımı ve doğrusal sistem','Tekrarlanan yamukların dış taban dizileri iki farklı kenar uzunluğunu ifade eder;çözüm iç boşluğa dönüşür.',
 'Dış ölçüleri26×16,kalınlığı her yanda1 olan çerçevenin iç ölçüleri nedir?',['25×15','24×14','24×15','25×14','22×12'],1,'Her ölçüden iki yandaki1’er birim çıkarılır;26−2=24,16−2=14 olur.','A');
 add(275,'Orta noktalarda eş alanların zinciri','Üçgende alan','TYT-mat',137,
 'İç noktadan kenar orta noktalarına çizilen parçaların aynı kenara ait iki küçük üçgeni eş alanlı yaptığını kullanarak alternatif alan toplamlarını eşitlemeyi ölçer.',
 ['Aynı yükseklik ve eş yarım taban taşıyan iki üçgenin alanları eşittir.','Beşgen çevresindeki bu eş parçalar eşleştirildiğinde A+4+7=B+5+8 ilişkisi oluşur.'],
 ['Bilinen alanları iki tarafa topla:A+11=B+13.','A−B=2 birimkare bulunur. Doğru seçenek C’dir;beşgenin düzgün olması veya iç noktanın merkez olması gerekmez.'],
 'Renkli dörtgenleri eş alanlı varsaymak gereksiz ve yanlış bir simetri ekler;eşlik yalnız kenarların yarım tabanlı küçük üçgenleri içindir.',
 'Aynı yükseklikte alan oranı','Orta nokta tabanı iki eş parçaya böler;alan oranı taban oranına eşit olduğundan yerel eşlikler küresel toplam bağıntısı verir.',
 'A+4+7=B+5+8 ise A−B kaçtır?',['0','1','2','3','4'],2,'A+11=B+13 eşitliği A−B=2 sonucunu verir.','C');
 add(276,'İki dik üçgende değişmeyen yatay uzaklık','Pisagor teoremi','TYT-mat',132,
 'Sensör aynı doğrultuda60 cm kayarken çubuğun yatay ofsetinin değişmediğini kullanıp iki hipotenüs karesini çıkararak son dik uzaklığı bulmayı ölçer.',
 ['Son dik uzaklık d,yatay ofset h ise d²+h²=130² olur.','İlk durumda dik uzaklık d+60’tır;(d+60)²+h²=170² yazılır.'],
 ['Eşitlikleri çıkar:120d+3600=28900−16900=12000.','120d=8400,d=70 cm bulunur. Doğru seçenek D’dir;170−130=40 sensörün yol değişimi değildir.'],
 'Hipotenüslerin farkını geri gidilen60’a eşitlemek uzaklığın eğik ölçüldüğünü kaçırır;sabit yatay ofset nedeniyle doğrusal fark geçerli değildir.',
 'Kare farkıyla sadeleştirme','İki Pisagor denklemindeki ortak h² terimi çıkarılınca tek doğrusal denklem kalır;yatay ofseti hesaplamak gerekmez.',
 '(d+60)²−d²=12000 ise d kaçtır?',['50','60','70','80','90'],2,'120d+3600=12000,120d=8400,d=70 bulunur.','D');
 add(277,'Yırtık eşitlikte üç olası ikizkenar kurgu','Üçgende açı','TYT-mat',115,
 'BE=BD koşuluna EA,ED veyaEC eşitliğini ayrı ekleyip görünen28° açıdan çıkan iki farklı x sonucunu karşılaştırmayı ölçer.',
 ['ABC’de A açısı62°’dir;β=∠ABE alınırsa x=∠AEB=118°−β olur.','EA=BE için ABE ikizkenarından β=62°,EC=BE için BEC ikizkenarından yineβ=62° elde edilir.'],
 ['Bu iki okumada x=56° olur. ED=BE=BD okumasında BED eşkenardır;∠EBD=60°,β=30° ve x=88° çıkar.','Hatalı ve doğru cevap farklı olduğundan fark|88−56|=32°,cevap C’dir.'],
 'Eksik parçayı rastgele seçip yalnız o üçgeni çözmek hangi sonuçların gerçekten farklı olduğunu göstermez;üç adayın sonuçları karşılaştırılmalıdır.',
 'Koşul senaryoları','Yırtık bilgi birden fazla model üretir;iki model aynı cevabı verse bile yanlış sonuç bilgisi farklı değer çiftini kesinleştirir.',
 'β=30° ve x=118°−β ise x kaçtır?',['56°','62°','80°','88°','90°'],3,'x=118°−30°=88° bulunur;bu değer eşkenar BED okumasının sonucudur.','C');
 add(278,'Eş yükseklikte köşelerden yatay köşegen','Dikdörtgen ve Pisagor','TYT-mat',148,
 'Dönen dikdörtgende B veD aynı yükseklikte olduğundan BD köşegeninin yatay olduğunu kullanıp30–40–50 üçgeninin yüksekliğini iki kat almayı ölçer.',
 ['ABD üçgeni A’da diktir;AB=30,AD=40,BD=50 olur.','A’dan yatay BD’ye dik yükseklik30·40/50=24’tür;dikdörtgen köşegenleri birbirini ortalar.'],
 ['BD’nin orta noktası AC’nin deorta noktasıdır. C yerde olduğundan A’nın BD üstündeki24 yüksekliği,B,D’nin yerden yüksekliğiyle aynıdır.','A’nın yerden yüksekliği h=24+24=48 bulunur. Doğru seçenek B’dir.'],
 'Dikdörtgen köşegeni50’yi A’nın yerden yüksekliği sanmak AC’nin son durumda düşey olmadığını unutur;yalnız BD yataylığı verilmiştir.',
 'Köşegenlerin ortak orta noktası','Dönme kenar ve köşegen uzunluklarını değiştirmez;orta nokta simetrisi A ileC’nin yatay BD’ye uzaklıklarını eşit yapar.',
 'Dik kenarları30,40 olan dik üçgenin hipotenüse yüksekliği kaçtır?',['18','20','24','30','40'],2,'Hipotenüs50’dir;alan eşitliğinden30·40/2=50h/2 ve h=24 çıkar.','B');
 add(279,'Bir köşedeki tam açıyı tamamlama','Düzgün çokgenler','TYT-mat',139,
 'Düzgün altıgenin120° ve karenin90° iç açılarıyla aynı köşede kalan150°’nin yeni düzgün çokgenin iç açısı olduğunu ölçer.',
 ['Bir nokta çevresindeki tam açı360°’dir.','Yeni çokgen iç açısı360−120−90=150° olur;dış açı180−150=30°’dir.'],
 ['Düzgün çokgende dış açıların toplamı360° olduğundan n=360/30=12 bulunur.','Doğru seçenek B’dir;ortak kenarların eş olması düzenli çokgenin kenar uzunluğu koşulunu da sağlar.'],
 'Kalan150°’yi doğrudan dış açı kabul etmek n’yi yanlış verir;bu açı çokgenin iç bölgesinde kalan açıdır.',
 'Yerel açıdan küresel kenar sayısı','Tek köşedeki düzgün iç açı bütün köşelerde aynıdır;dış açı360/n bağıntısı kenar sayısını belirler.',
 'İç açısı150° olan düzgün çokgen kaç kenarlıdır?',['8','10','12','15','18'],2,'Dış açı30°’dir.360/30=12 kenar bulunur.','B');
 add(280,'Dönen ışınlarda adım sayısı ve açı','Açı ve sayma','TYT-mat',113,
 'İlk ışının dönüşsüz olduğunu dikkate alıp A’nın2. ve8. ışınlarını α,7α;B’nin3. ve5. ışınlarını2β,4β dönüşleri olarak modellemeyi ölçer.',
 ['İlk diklikten α+2β=90° çıkar.','İkinci ışın çifti dikliği7α+4β=270° verir;90° seçimi pozitif α ileçelişir.'],
 ['İlk eşitliğin iki katını ikinciden çıkar:5α=90°,α=18°;β=36° olur.','Şekilde ilk yukarı ışından son aşağı ışına yarım tur180° gösterilir. A için180/18=10 dönüş ve ilk ışınla11 ışın vardır;cevap B’dir.'],
 '180/18=10’u ışın sayısı seçmek başlangıçtaki dönüşsüz1. ışını unutur;dönüş sayısından bir fazla ışın çıkar.',
 'İndis ve dönüş sayısı','k. ışın(k−1) sabit açı adımından sonra gönderilir;ışın etiketleri açı eşitliklerine böyle çevrilir.',
 'Bir cihaz başlangıç ışını dahil18° adımlarla180° dönerse kaç ışın gönderir?',['9','10','11','12','18'],2,'180/18=10 dönüş vardır. Başlangıç ışını eklenince11 ışın elde edilir.','B');
 all['q-ayt-matematik-280'].note='Kaynak metinde toplam dönüş açısının sayısı görünmüyor;şekilde ilk yukarı ve son aşağı ışın yarım turu(180°) gösteriyor.11 ışın sonucu bu görsel koşulla elde edilmiştir.';
 add(281,'Eş yükseklikli üçgende üst alan oranı','Benzerlik ve alan','TYT-mat',120,
 'Paralel kesimlerde üst küçük üçgenin yüksekliği bütünün üçte biri olduğundan alanının dokuzda biri olduğunu kullanıp yüzde20 düzenlemesindeki artışı ölçer.',
 ['Benzer üçgenlerde alan oranı benzerlik oranının karesidir;ilk davranış bölmesi toplam alanın1/9’udur.','Yeni istenen davranış alanı toplamın%20’si,yani1/5’idir;poster toplam alanı değişmez.'],
 ['Artış(1/5−1/9)T=(4/45)T=24 olarak yazılır.','T=24·45/4=270 birimkare bulunur. Doğru seçenek A’dır;başlangıçta yazılan%20 alan oranını henüz göstermemektedir.'],
 'Üç bölmenin yüksekliği eşit diye alanlarını eşit saymak üçgenin yatay genişliğinin yükseklikle değiştiğini unutur.',
 'Ölçek karesi','Doğrusal yükseklik oranı alan hesabında karesine çıkarılır;bu,paralel kesim sorularının temel dönüşümüdür.',
 'Bir üçgenin tepesindeki benzer küçük üçgen yüksekliğin1/4’ünü taşıyorsa alan oranı kaçtır?',['1/2','1/4','1/8','1/16','1/32'],3,'Benzerlik oranı1/4 olduğundan alan oranı(1/4)²=1/16’dır.','A');
 add(282,'Üç eş tepe açısının yön farkı','İkizkenar üçgende açı','TYT-mat',115,
 'Eş ikizkenar üçgenlerin ince tepe açılarının her yerleştirmede kenar doğrultusunu aynı miktarda çevirdiğini kullanıp toplam48° farkı üçe bölmeyi ölçer.',
 ['Üç eş üçgenin ince tepe açıları θ,iki eş taban açıları(180−θ)/2’dir.','Sarı üst eş kenar yataydır;çakışan kenarlar boyunca pembe ve mavi kenarlara geçişte üçθ toplam dönüşü oluşur.'],
 ['Mavinin alt kenarla48° yaptığı şekil koşulu3θ=48°,θ=16° verir.','İstenen eş açı(180−16)/2=82°’dir. Doğru seçenek E’dir;48° doğrudan ikizkenar üçgenin iç açısı değildir.'],
 'Üst ve alt kâğıt kenarlarının paralelliğini kullanmadan48°’yi taban açısı seçmek kenarlar arasındaki zincirli yön değişimini atlar.',
 'Paralel doğrulara açı taşıma','Aynı yatay doğrultu iki kâğıt kenarında ortaktır;üç eş tepe dönüşü bu ortak eksene göre karşılaştırılır.',
 'Tepe açısı16° olan ikizkenar üçgenin eş taban açıları kaçtır?',['72°','76°','78°','80°','82°'],4,'İki taban açısı toplam164° olduğundan her biri82°’dir.','E');
 add(283,'Katlanmış tabanın yarı genişliği','Pisagor ve çevre','TYT-mat',132,
 'Takvimin kare yüz kenarı s,ilk taban derinliği b ilekatlanınca görünen turuncu dikdörtgenin b/2 derinlikte olduğunu kullanmayı ölçer.',
 ['Beyaz kare çevresi4s,görünen turuncu dikdörtgen çevresi2s+b’dir;fark12 olduğundan b=2s−12 olur.','İlk yan görünümde eş kenarlar s,yükseklik12,tabanın yarısı b/2’dir; s²=12²+(b/2)² yazılır.'],
 ['b/2=s−6 ile s²=144+(s−6)²,12s=180,s=15 bulunur.','b=18 ve ilk turuncu karton çevresi2(15+18)=66 cm’dir. Doğru seçenek C’dir.'],
 'Şekil3’te görünen turuncu parçayı ilk tabanın tamamı sanmak ortadan katlamayı unutup çevre farkını yanlış kurar.',
 'Üç boyutlu modelden kesit','Takvimin yandan kesiti ikizkenar üçgendir;kare ön yüz kenarı aynı zamanda bu kesitin eş kenarıdır.',
 'Eş kenarı15,yüksekliği12 olan ikizkenar üçgenin tabanı kaçtır?',['12','15','18','20','24'],2,'Yarım taban√(225−144)=9’dur. Tam taban18 bulunur.','C');
 add(284,'Yüksekliklerde ters orantı ve üçgen eşitsizliği','Üçgende alan','TYT-mat',137,
 'AB=BC/2 koşulunun ilgili yüksekliklerde2 oranı verdiğini kullanıp önerilen üçüncü yüksekliğin kenarları geçerli üçgen yapıp yapmadığını ölçer.',
 ['Aynı alan için kenar·yükseklik sabittir;yükseklikler4,10,t ise kenarlar1/4,1/10,1/t ileorantılıdır.','AB=BC/2 nedeniyle yüksekliklerden bir çiftin oranı2 olmalıdır;aday2,5,8 bunu farklı eşleştirmelerle sağlayabilir.'],
 ['t=2 için1/2>1/4+1/10,t=8 için1/4>1/8+1/10;iki üçgen eşitsizliği bozulur.','t=5 için kenarlar1/4,1/5,1/10 geçerli üçgen oluşturur. Yalnız II,cevap B’dir.'],
 'Yalnız2 oranını kontrol etmek yeterli değildir;yükseklikler aynı zamanda üç gerçek kenarın tersleri olarak üçgen eşitsizliğine uymalıdır.',
 'Alan ve ters uzunluk','Yükseklik oranından kenar oranına geçerken ters alma yapılır;son geometrik varlık kontrolü kenarlarda uygulanır.',
 'Kenarları1/2,1/4,1/10 olan üçgen var mıdır?',['Evet','Hayır;en büyük kenar diğerleri toplamından büyük.','Yalnız dikse','Yalnız eşkenarsa','Alan verilmeden bilinmez'],1,'1/4+1/10=7/20<1/2 olduğundan üçgen eşitsizliği sağlanmaz.','B');
 add(285,'İki eşkenar üçgende30–60–90 alan oranı','Benzerlik ve alan','TYT-mat',123,
 'Dikey kırmızı kenar ileyatay mavi taban sayesinde oluşan sarı ve gri üçgenlerin30–60–90 olduğunu görüp alan oranını uzunluk oranına çevirmeyi ölçer.',
 ['Gri üçgende kısa dik kenar x seçilirse alan√3x²/2 olur.','Sarı üçgenin hipotenüsü t ise alan√3t²/8’dir;alanının dört kat olması t=4x verir.'],
 ['Kırmızı eşkenarın bir kenarı t+x=5x olur. Mavi tepe yüksekliği5x−x/2=9x/2 olduğundan mavi kenar3√3x’tir.','Eşkenar alanları kenar kareleriyle orantılıdır;oran25x²/(27x²)=25/27,cevap D’dir.'],
 'Sarı–gri alan oranı4’ten tüm eşkenar kenarların oranını2 sanmak bu küçük üçgenlerin büyük şekillerin tamamı olmadığını unutur.',
 'Özel üçgen ve alan ölçeği','Alan oranı önce benzer küçük parçaların belirli kenarlarına uygulanır;sonra bu parçalar büyük eşkenarların kenar ve yüksekliğini oluşturur.',
 'Eşkenar üçgen kenarları5x ve3√3x ise alanları oranı kaçtır?',['5/9','25/9','25/27','5/27','27/25'],2,'Oran kenar oranının karesidir:25x²/(27x²)=25/27.','D');
 add(286,'İç ortak kenarı çevreden çıkarma','İkizkenar üçgen alanı','TYT-mat',115,
 'İki küçük çevre toplamından büyük çevreyi çıkarıp iç kenarıniki kez sayıldığını kullanmayı,sonra isosceles simetrisiyle yüksekliği bulmayı ölçer.',
 ['İç kenar d=(16+21−24)/2=13/2’dir.','Küçük üçgen tabanlarının farkı21−16=5;ikizkenar büyük üçgen taban orta noktasından iç taban noktasına yatay uzaklık5/2’dir.'],
 ['Yükseklik√[(13/2)²−(5/2)²]=6 bulunur. Büyük eş kenar L,yarım taban t için L+t=12 ve L²=t²+36 olur.','Buradan t=9/2,taban9 ve alan9·6/2=27’dir. Doğru seçenek B’dir.'],
 'Çevreler farkını doğrudan iç kenar saymak ortak kenarıniki küçük çevrede deyer aldığını unutmak demektir.',
 'Simetriyle dik üçgen','İkizkenar yüksekliği tabanı ikiye böler;taban parçaları farkı5,işaretli yatay sapmayı yarısı5/2 yapar.',
 'Dik üçgende hipotenüs13/2,bir dik kenar5/2 ise diğer dik kenar kaçtır?',['4','5','6','7','8'],2,'Diğer kenar²=(169−25)/4=36 olduğundan kenar6’dır.','B');
 add(287,'Dairelerin örttüğü kenar parçaları','Pisagor ve daire alanı','TYT-mat',132,
 'Her üçgen kenarının iki ucunda r’şer uzunluk daire içinde kaldığından kenarları2r+2,2r+3,2r+5 yazarak yarıçapı bulmayı ölçer.',
 ['d=2r için dik kenarlar d+2,d+3,hipotenüs d+5’tir.','Pisagor(d+2)²+(d+3)²=(d+5)² eşitliği d²=12,r²=3 verir.'],
 ['Üç köşedeki daire içi üçgen sektörlerinin açıları toplam180° olduğundan içeride kalan toplam alanπr²/2’dir.','Dışarıda kalan3πr²−πr²/2=5πr²/2=15π/2 bulunur. Doğru seçenek E’dir.'],
 'Üç köşedeki sektörleri üç yarım daire sanmak açıların toplamının180° olduğunu atlar;tek bir yarım daire alanına eşdeğerdir.',
 'Açı toplamından sektör alanı','Sektörlerin yarıçapları eşit olduğunda alanları yalnız açılarıyla orantılıdır;üçgenin açı toplamı tek hamlede toplamı verir.',
 'r²=3 ise üç daire alanından180° toplam sektör çıkarılınca kaç alan kalır?',['3π','9π/2','6π','15π/2','9π'],3,'3πr²−πr²/2=(5/2)π·3=15π/2’dir.','E');
 add(288,'İki yarım çemberin ortak alanı','Çemberde alan','AYT-mat',125,
 'Merkezlerin birbirinin çemberinde olmasıyla12 kenarlı eşkenar merkez üçgenini kurup tam mercek alanından yarım çember sınırlarının kestiği iki daire parçasını çıkarmayı ölçer.',
 ['İki tam çemberin kesişim merceği iki120° sektör eksi iki eşkenar üçgendir:96π−72√3.','Yarım çember çaplarının dışladığı iki eş parça,her biri60° sektör eksi eşkenar üçgen alanıyla24π−36√3’tür.'],
 ['Boyayı tam mercek sanmadan bu iki parçayı çıkar.','(96π−72√3)−2(24π−36√3)=48π bulunur. Doğru seçenek C’dir;üçgenli terimler birbirini tamamen giderir.'],
 'Yalnız tam çember mercek formülünü kullanmak kaynakta iki yarım çember bulunduğunu atlar;çap doğruları ortak bölgeden iki ek parça keser.',
 'Yarıçap ve merkez uzaklığı','Merkezler arası uzaklık da12 olduğu için kesişim üçgenleri eşkenardır;60° ve120° merkez açıları buradan gelir.',
 'Yarıçapı12 olan dairede120° sektör alanı kaçtır?',['24π','36π','48π','60π','72π'],2,'Alan(120/360)π·12²=48π’dir. Sektör alanı üçgen çıkarılmış daire parçasından farklıdır.','C');
 add(289,'Dönme dolapta yatay simetri anı','Çemberde açı','AYT-mat',115,
 'İki kabinin sabit48° merkez açı farkını koruduğunu kullanıp yüksekliklerinin eşit olmasını üst düşey eksenin iki yanında simetrik olmalarıyla ölçer.',
 ['Nisa bindiğinde onun açısı alt noktadan0,Meryem’inki48° ileridedir.','Nisa bindikten sonraki dönüşθ ise kabin açılarıθ veθ+48° olur;ilk eş yükseklikte üst nokta180° bu ikisinin ortasıdır.'],
 ['[θ+(θ+48)]/2=180 eşitliğini kur.','θ+24=180,θ=156° bulunur. Doğru seçenek E’dir;48° öncesindeki dönüş sorulan son süreye yeniden eklenmez.'],
 'İki kabin yan yana aynı yüksekliğe yalnız altta gelir sanmak çemberde yatay bir doğrunun iki yanda simetrik iki noktası olduğunu unutur.',
 'Kosinüsle eşit yükseklik','Alt noktadan ölçülen açıda yükseklik r−r cosθ’dir;cosθ=cos(θ+48°) aynı simetri koşulunu verir.',
 'İki kabin arası merkez açı40° ise ikinci binişten sonra ilk eş yüksekliğe kaç derece sonra gelir?',['140','150','160','170','180'],2,'θ+20=180 olmalıdır. Bu yüzden θ=160° bulunur.','E');
 add(290,'Üç dilimle yarım daireyi tamamlama','Daire dilimi','AYT-mat',125,
 'İki büyük veon bir küçük özdeş dilimin toplam360° açısını,üç dilimden oluşan180° koşuluyla birlikte kurmayı ölçer.',
 ['Büyük açıα,küçükβ için2α+11β=360°’dir.','Üç dilimde0 veya1 büyük kullanmak pozitif açılarla toplamı sağlayamaz;uygun yarım daire iki büyük bir küçüktür.'],
 ['2α+β=180° eşitliğini bütün pizza denkleminden çıkar:10β=180°,β=18° bulunur.','2α=162°,α=81° olur. Doğru seçenek B’dir;dilim adedi alan değilmerkez açı toplamına dönüşür.'],
 'Her dilimi360/13 eşit açı saymak iki farklı özdeş grup bulunduğunu yok sayar;yalnız kendi grubundaki dilimler eşittir.',
 'Açıların toplamsallığı','Aynı merkezli daire dilimleri yan yana birleşince merkez açıları doğrudan toplanır;yarım daire180° koşuludur.',
 '2α+β=180°,β=18° ise α kaçtır?',['72°','75°','80°','81°','90°'],3,'2α=162° olduğundan α=81° bulunur.','B');
 add(291,'Top geçişinde içteğet daire çapı','Çokgen ve daire','TYT-mat',139,
 'Yarıçapı2 olan kürenin tel düzleminden geçerken4 cm çaplı dairesel kesit için boşluk bulunması gerektiğini her örgü biçiminde ölçer.',
 ['5 cm kare boşluğun içteğet yarıçapı2,5 cm’dir;2 yarıçaplı kesit değmeden sığar.','6 cm eşkenar üçgenin içyarıçapı√3;kenarı4,60° açılı eşkenar dörtgenin içyarıçapı da√3 cm’dir.'],
 ['II veIII boşluklarının en dar açıklığı2√3<4 olduğundan top geçemez.','Yalnız I mümkündür;cevap A’dır. Uzun kenarın top çapından büyük olması tek başına yeterli değildir.'],
 'Üçgen kenarı6>4 diye geçer demek boşluğun merkezden kenarlara olan uzaklığını hesaba katmaz;belirleyici içteğet yarıçaptır.',
 'Küre ve düzlem kesiti','Topun merkezi tel düzleminden geçerken en büyük kesit yarıçapı2’dir;örgü boşluğu bu daireyi içermelidir.',
 'İçteğet yarıçapı√3 olan boşluktan yarıçapı2 daire değmeden geçer mi?',['Evet','Hayır','Yalnız eğikse','Yalnız kareyse','Çevresi bilinmeli'],1,'√3<2 olduğundan boşluğa sığan en büyük daire yeterince büyük değildir.','A');
 add(292,'Küçük daire parçasında kiriş uzunluğu','Çemberde kiriş','AYT-mat',115,
 'İlk yarım güneş görüntüsünden yarıçap3,9 cm’yi bulup ikinci resimde0,3 cm yüksek daire parçasının kirişini hesaplamayı ölçer.',
 ['İlk yarım dairede en üst noktanın çap doğrusuna uzaklığı yarıçap3,9’dur.','İkinci resimde merkezden deniz kirişine uzaklık3,9−0,3=3,6 cm’dir.'],
 ['Kirişin yarısı t için t²+3,6²=3,9² yaz.','t²=15,21−12,96=2,25,t=1,5 olur. Tam kiriş2t=3 cm,cevap C’dir.'],
 '0,3’ü merkezden kirişe uzaklık almak daire parçasının yüksekliğiyle merkez mesafesini karıştırır;yarıçaptan çıkarılmalıdır.',
 'Kirişin orta dikmesi','Merkezden kirişe dik doğru kirişi ikiye böler;Pisagor bütün kiriş yerine yarısını verir.',
 'Yarıçap5,merkezden kirişe uzaklık4 ise kiriş uzunluğu kaçtır?',['3','4','5','6','8'],3,'Yarım kiriş√(25−16)=3 olduğundan tam kiriş6’dır.','C');
 add(293,'Sabit merkezlerde dış ve iç teğetlik','Çemberlerin konumu','AYT-mat',127,
 'Merkez uzaklığı değişmeden yarıçaplar iki veüç kat yapılınca oluşan iki farklı teğetliği toplam ve fark eşitlikleriyle modellemeyi ölçer.',
 ['İki kat durumda merkez uzaklığı d=2(R+r),dış teğetliktir.','Üç kat durumda d=3(R−r),iç teğetliktir;ölçek büyüdükçe önce dış temas,sonra iç temas gerçekleşir.'],
 ['2(R+r)=3(R−r) eşitliğinden2R+2r=3R−3r yaz.','R=5r ve R/r=5 bulunur. Doğru seçenek C’dir;iki durumda daaynı teğetlik türü olsaydı sabit d ileuyuşmazdı.'],
 'İki teğetliği deyarıçaplar toplamı saymak2(R+r)=3(R+r) gibi olanaksız eşitlik üretir;ikinci temas iç teğetliktir.',
 'Teğet çember koşulları','Dış teğetlikte merkez uzaklığı toplam,iç teğetlikte farktır;merkezlerin korunması bu iki ölçüyü eşitler.',
 '2(R+r)=3(R−r) için R/r nedir?',['2','3','4','5','6'],3,'Düzenleyince R=5r çıkar. Küçük yarıçap pozitif olduğundan oran5’tir.','C');
 add(294,'Saat çizgilerinden yarıçapı bulma','Çemberde koordinat ve açı','AYT-mat',115,
 'Saatin30° aralıklı işaretlerinde1–5 ve7–11 doğrularının merkeze R/2 uzaklıkta dikey kiriş doğruları oluşturduğunu kullanmayı ölçer.',
 ['Sağdaki1 ve5 uçları x=R/2,soldaki7 ve11 uçları x=−R/2 doğrularındadır.','Kordonun2 cm genişliği bu doğrular arası R uzaklığıdır;dolayısıyla yarıçap2,çap4 cm’dir.'],
 ['Her kordonun uzunluğu L olsun;teğet kısa kenarlar arasında saat çapı4 vardır.','2L+4=25,L=21/2=10,5 cm bulunur. Doğru seçenek E’dir;kordonlar ekranın içine uzatılmaz.'],
 '2 cm kordon genişliğini doğrudan çap saymak işaretlerin çemberin en sağ veen sol uçlarında olmadığını gözden kaçırır.',
 'Özel açılı izdüşüm','1 ve5 saat yönleri düşey eksene30° yaptığı için yatay izdüşüm Rsin30°=R/2 olur.',
 'Toplam uzunluk25,orta daire çapı4 veiki eş kordon varsa tek kordon uzunluğu kaçtır?',['9,5','9,75','10','10,25','10,5'],4,'İki kordon toplamı25−4=21’dir. Eş uzunlukların her biri10,5 cm olur.','E');
 add(295,'45 derecelik sektörden küçük üçgen çıkarma','Daire dilimi alanı','AYT-mat',125,
 'Çeyrek dairenin yarısının45° sektör olduğunu veikinci kesimin r/2 dik kenarlı ikizkenar dik üçgen ayırdığını ölçer.',
 ['Kalan45° sektör alanıπr²/8’dir.','Sarı üçgenin iki dik kenarı r/2 olduğundan alanı½(r/2)²=r²/8 olur.'],
 ['Mavi alanπr²/8−r²/8=(π−1)r²/8 bulunur.','Mavi/sarı oranıπ−1’dir;doğru seçenek B’dir. İlk kesimde atılan diğer yarı artık sonraki alanlara dahil edilmez.'],
 'Sarı parçayı r²/4 saymak üçgen alanındaki1/2 çarpanını unutmak demektir;dik kenarların her ikisi der/2’dir.',
 'Ölçekten bağımsız oran','Her iki alan aynı r²/8 çarpanını taşıdığından yarıçapın sayısal değeri sonuçta sadeleşir.',
 'πr²/8 sektöründen r²/8 üçgen çıkarılırsa kalan/üçgen oranı nedir?',['π','π−1','π−2','π/2','2π/3'],1,'Kalan(π−1)r²/8’dir. r²/8’e bölününceπ−1 elde edilir.','B');
 add(296,'Dik kirişlerden çap ve daire parçası yüksekliği','Çemberde kiriş','AYT-mat',115,
 'BC⊥CD olduğundan BD’nin çap olmasını kullanıp verilen daire parçası yüksekliklerini merkez–kiriş uzaklıklarına dönüştürmeyi ölçer.',
 ['Yarıçap R,kirişin yay orta noktasına yüksekliği h ise merkez uzaklığı R−h’dir.','BCD dik üçgeni için(R−5)²+(R−10)²=R² olur;R=5 veya25 çıkar ve10 yüksekliği nedeniyle R=25 seçilir.'],
 ['BAD deçapı gören dik üçgendir;(25−1)²+(25−x)²=25² yaz.','24²+(25−x)²=625,|25−x|=7 olur. Küçük yay parçası x≤25 olduğundan x=18;cevap E’dir.'],
 'h’yi merkezden kirişe uzaklık sanmak verilen kırmızı uzunluğun yaydan kirişe kadar ölçüldüğünü kaçırır;uzaklık R−h’dir.',
 'Çapı gören dik açı','BD çapı iki ayrı dik üçgen oluşturur;aynı yarıçap denklemi önceR’yi,sonra x’i belirler.',
 '24²+(25−x)²=625 ve0<x<25 ise x kaçtır?',['16','17','18','19','20'],2,'(25−x)²=49 ve25−x>0 olduğundan25−x=7,x=18 olur.','E');
 add(297,'Dilim paylarından yarıçap kare oranı','Daire alanı','AYT-mat',125,
 'Ali’nin beş tam dış daire dilimiyleAyşe’nin üç iç malzemeli dilimini karşılaştırıp alan oranından yarıçap oranının karekökünü almayı ölçer.',
 ['Ali alanı5πR²/8,Ayşe alanı3πr²/8’dir.','Verilen oran2,4=12/5 olduğundan5R²/(3r²)=12/5 olur.'],
 ['R²/r²=(12/5)(3/5)=36/25 bul.','Yarıçaplar pozitif olduğundan R/r=6/5 seçilir. Doğru seçenek D’dir;alan oranı doğrudan yarıçap oranı değildir.'],
 'Ayşe’nin deüç tam pizza dilimini yediğini varsaymak sarı dış kenarı dahil eder;yalnız turuncu iç daire bölgesi yenmiştir.',
 'Kare ölçek yasası','Eş merkezli dairelerin alanları yarıçap kareleriyle orantılıdır;dilim adetleri bu alanlara ayrı kesir katsayıları getirir.',
 'R²/r²=36/25 veR,r>0 ise R/r kaçtır?',['3/2','4/3','5/4','6/5','7/6'],3,'Pozitif karekök alındığında R/r=6/5 bulunur.','D');
 add(298,'Sabit yay uzunluğunda askı yüksekliği','Yay uzunluğu ve kiriş','AYT-mat',124,
 'Aynı telin120° ve180° yaylarında farklı yarıçaplar oluşturmasını kullanıp çividen tabloya düşey mesafe artışını8’e eşitlemeyi ölçer.',
 ['Tel uzunluğu L için ilk yarıçap3L/(2π),ilk yay yüksekliği R(1−cos60°)=3L/(4π)’dir.','Yarım çemberde yarıçap veyay yüksekliği L/π olur;çivi aynı yerde kaldığı için artan yükseklik tabloyu aşağı indirir.'],
 ['L/π−3L/(4π)=8 eşitliğini kur.','L/(4π)=8,L=32π bulunur. Doğru seçenek C’dir;telin uzunluğu korunur fakat yarıçapı korunmaz.'],
 'İki durumda aynı yarıçapı kullanmak bükülen telin yay açısı değişince uzunluk=açı×yarıçap bağıntısını bozmasıdır.',
 'Yay yüksekliği','120° yayın orta dikmesinde yarım merkez açı60° olur;kirişten en üst noktaya mesafeR−Rcos60°’dir.',
 'L/(4π)=8 ise L kaçtır?',['24π','28π','32π','36π','40π'],2,'Her iki taraf4π ile çarpılınca L=32π elde edilir.','C');
 add(299,'Askı kirişinin merkez uzaklığından yarıçap','Çemberde kiriş','AYT-mat',115,
 'İlk iki askı noktasının48 birim kiriş oluşturmasını vetek ipte askı noktasının dairenin en üstüne dönmesini kullanarak merkez düşüşünü16’ya bağlamayı ölçer.',
 ['Kirişin yarısı24,merkezden kirişe uzaklık d olsun;24²+d²=R²’dir.','İp uzunluğu değişmediği için askı seviyesi aynıdır;tek ipte merkezR kadar aşağıdadır. DüşüşR−d=16 olur.'],
 ['d=R−16 ile576+(R−16)²=R² yaz.','32R=832,R=26 bulunur. Doğru seçenek B’dir;verilen16 yalnız plakanın alt kenarı değilmerkezinin deaynı düşüşüdür.'],
 '16’yı doğrudan yarıçap sanmak iki ipte merkezin askı seviyesinin altında zaten d kadar bulunduğunu unutur.',
 'Katı cismin ötelenmesi','Dairenin boyutu değişmediğinden alt nokta vemerkez aynı miktarda alçalır;bu,sorudaki yükseklik farkını merkez denklemine taşır.',
 '24²+(R−16)²=R² için R kaçtır?',['24','25','26','28','30'],2,'576+R²−32R+256=R²,32R=832 veR=26 bulunur.','B');
 add(300,'Sektörler iptal olunca üçgen alan oranı','Çemberde açı ve alan','AYT-mat',125,
 '18° çevre açıdan BD yayının36°,AD yayının144° olduğunu çıkarıp sektör alanlarının4 oranını renkli alan eşitliğinde sadeleştirmeyi ölçer.',
 ['O merkez olsun;AOD sektörü BOD sektörünün4 katıdır.','Sarı alan AOD sektörü eksi AOD üçgeni,mavi alan BOD sektörü eksi COD üçgeni olarak yazılır;C’nin O’nun sağında olduğu pozitif oranla doğrulanır.'],
 ['Sarı=4mavi koşulunda sektörler gider ve alan(AOD)=4alan(COD) kalır.','Ortak D yüksekliği nedeniyle AO=4CO;CO=R/4 olur. AC=5R/4,BC=3R/4 veoran5/3,cevap B’dir.'],
 'Renkli alanları yalnız sektör saymak AD veCD kirişlerinin kestiği üçgenleri unutur;18° açı alan eşitliğinde bu üçgenler üzerinden uzunluğa dönüşür.',
 'Ortak yükseklikte taban oranı','AOD veCOD üçgenlerinin D’den AB’ye yükseklikleri aynı olduğundan alan oranı AO/CO’ya eşittir.',
 'AO=OB=R,CO=R/4 veC,O ileB arasındaysa AC/BC kaçtır?',['3/2','5/3','7/4','7/5','9/5'],1,'AC=R+R/4=5R/4,BC=R−R/4=3R/4 olduğundan oran5/3 olur.','B');
 add(301,'Aynı renk iki karşılaşmadan çevreyi bulma','Çemberde yay ve dönme','AYT-mat',124,
 'Yuvarlanan tekerlekte ardışık iki mavi çakışmanın bir tam tur olduğunu fark edip kırmızı ile mavi arasındaki yolu merkez açıya çevirmeyi ölçer.',
 ['Kaymadan dönmede alınan yol, dönülen yayın uzunluğudur.','Mavi parçayla ilk ve ikinci çakışmalar arasındaki 290−90=200 cm, tekerleğin çevresidir.'],
 ['Maviden kırmızıya geçerken 130−90=40 cm yol alınır; bu, tam turun 40/200=1/5’idir.','Aradaki merkez açı 360/5=72° olur. Şekilde istenen dar açı da budur; doğru seçenek D’dir.'],
 '290 cm’yi çevre kabul etmek başlangıçtaki siyah telin maviyle çakışmadığını gözden kaçırır; çevre iki aynı renkli karşılaşmanın farkıdır.',
 'Oran ve periyodiklik','Aynı konuma dönüş periyodu bulununca farklı konumlar arasındaki yol, açı oranına doğrudan çevrilir.',
 'Bir tel aynı sabit parçayla ilk kez 50, ikinci kez 230 cm sonra çakışıyor. Başka parçayla ilk çakışması 80 cm’deyse iki parçanın dar açısı kaçtır?',['30°','45°','60°','75°','90°'],2,'Çevre 230−50=180, iki konum arası yol 30 cm’dir. Açı 360·30/180=60° olur.','D');
 add(302,'Eşit kirişlerden çap doğrultusunu belirleme','Çemberde kiriş ve yay','AYT-mat',120,
 'P’den çıkan eşit açılı beş ışında PK=PM simetrisini kullanarak en uzun kirişi çap olarak belirlemeyi ve kırmızı yayın gerçek merkez açısını bulmayı ölçer.',
 ['Aynı uçtan çizilen eşit kirişler, o uçtan geçen çap doğrultusuna göre simetriktir.','PK ve PM arasındaki açıortay PL olduğundan PL çaptır; çap 30, yarıçap 15 birimdir.'],
 ['PR=15, yarıçapa eşittir. Merkezle P ve R’nin oluşturduğu üçgen eşkenardır; küçük PR yayı 60°’dir.','Kırmızı yay şekilde küçük PR yayıdır. Uzunluğu 2π·15·60/360=5π bulunur; doğru seçenek B’dir.'],
 'P’deki çevre açısını doğrudan yay açısı saymak veya 15’i çap almak sonucu yarıya indirir; önce merkezi içeren üçgen kurulmalıdır.',
 'Simetri ve merkez açı','Eşit kiriş koşulu çapı saptar; kirişin yarıçapa eşit olması yay ölçüsünü sayısal hâle getirir.',
 'Yarıçapı 12 olan çemberde bir kirişin uzunluğu da 12’dir. Bu kirişin gördüğü küçük yayın uzunluğu kaçtır?',['2π','3π','4π','6π','8π'],2,'Merkez ve kiriş uçları eşkenar üçgen oluşturur. 60°’lik yayın uzunluğu 24π/6=4π’dir.','B');
 add(303,'Ağırlık merkezinden iki köşeyi çözme','Üçgenin analitik incelenmesi','AYT-mat',99,
 'İki köşenin y=x ve y=−x üzerinde olmasını parametrik koordinatlara dönüştürüp ağırlık merkeziyle alanı hesaplamayı ölçer.',
 ['Orijin dışındaki köşeler P=(a,a) ve Q=(b,−b) biçiminde yazılabilir.','Ağırlık merkezinin koordinatları üç köşenin koordinatlarının aritmetik ortalamasıdır.'],
 ['Merkez (2,4) olduğundan a+b=6 ve a−b=12; buradan a=9, b=−3 bulunur.','Köşeler (9,9), (−3,3) olur. Orijinli üçgenin alanı |9·3−9·(−3)|/2=27’dir; doğru seçenek C’dir.'],
 'Ağırlık merkezi koordinatlarını ikiye bölme kuralıyla kullanmak, orta nokta ile ağırlık merkezini karıştırır; toplamlar üçle çarpılmalıdır.',
 'Determinantla alan','Doğru denklemleri köşelerin koordinatlarını sınırlar; bu koordinatlar orijinli alan formülünde doğrudan kullanılır.',
 'O=(0,0), P=(a,a), Q=(b,−b) üçgeninin ağırlık merkezi (1,3) ise alan kaçtır?',['9','12','18','24','27'],2,'a+b=3, a−b=9’dan a=6,b=−3 bulunur. Alan |6·3−6·(−3)|/2=18’dir.','C');
 add(304,'Eşit alan doğrusunun merkezden geçmesi','Doğrunun analitik incelenmesi','AYT-mat',100,
 'Kareyi iki eşit alana bölen doğrunun merkezden geçmesini kullanarak verilen eğimden x ekseni kesişimini bulmayı ölçer.',
 ['Şekilde kare [0,8]×[0,8] olduğundan merkezi (4,4)’tür.','Bir merkezî simetrik bölgeyi merkezden geçen her doğru iki eşit alana ayırır; sabit eğimde bu doğru tektir.'],
 ['Eğimi −1/4 olan merkez doğrusu y−4=−(x−4)/4, yani y=−x/4+5’tir.','x ekseninde y=0 konur: x=20. Buna göre a=20’dir ve doğru seçenek E’dir.'],
 'Doğrunun karenin bir köşesinden geçmesi gerektiğini varsaymak alan eşitliğinden çıkmaz; belirleyici nokta köşegenlerin kesişimidir.',
 'Merkezî simetri','Karenin karşılıklı noktaları merkez üzerinden eşleşir; bu eşleşme iki tarafta kalan alanların eşitliğini açıklar.',
 'Köşeleri (0,0),(6,0),(6,6),(0,6) olan kareyi eşit alanlara bölen, eğimi −1/2 olan doğrunun x keseni kaçtır?',['6','7','8','9','12'],3,'Merkez (3,3) için y−3=−(x−3)/2 yazılır. y=0 alınırsa x=9 bulunur.','E');
 add(305,'Üç doğrunun ortak noktasını kullanma','Doğru denklemleri','AYT-mat',100,
 'Üç ayrı noktadan ve eğimden kurulan doğruların ortak kesişim koşulunu iki denklemle belirlemeyi ölçer.',
 ['Doğrular y=mx+1, y=2mx ve y=3m(x−1) biçimindedir.','İlk iki doğru ortak noktada mx=1 verir; m=0 bu eşitliği sağlayamaz.'],
 ['Ortak noktada ikinci ve üçüncü eşitlenirse 2mx=3mx−3m, yani mx=3m olur.','mx=1 ile birlikte 3m=1 çıkar; m=1/3’tür. Ortak nokta (3,2) denklemlerin üçünü de sağlar; doğru seçenek B’dir.'],
 'Üçüncü doğruyu y=3mx+1 biçiminde yazmak verilen (1,0) noktasını yanlış kullanır; nokta-eğim biçimi x−1 gerektirir.',
 'Denklem sistemi','Geometrik ortak kesişim, aynı x ve y’nin üç doğrusal bağıntıyı birlikte sağlaması anlamına gelir.',
 'y=mx+2, y=2mx ve y=4m(x−1) doğruları tek noktada kesişiyorsa m kaçtır?',['1/4','1/2','1','2','4'],2,'İlk iki doğru mx=2 verir. Son ikisi 2mx=4mx−4m, yani mx=2m gerektirir. Böylece m=1’dir.','B');
 add(306,'Kare kenarını ordinat farkından kurma','Kare ve doğru denklemi','AYT-mat',100,
 'y eksenindeki iki köşenin farkını kare kenarı olarak kullanıp C’nin doğru üzerinde olmasıyla a ve b’yi belirlemeyi ölçer.',
 ['Şekilde A üstte, B altta olduğundan kare kenarı a−b’dir.','B=(0,b), C=(a−b,b), D=(a−b,a) olur; C’de y=x/3 sağlanır.'],
 ['b=(a−b)/3 eşitliğinden a=4b bulunur. a+b=15 olduğuna göre b=3 ve a=12’dir.','D=(9,12) olduğundan koordinatları toplamı 21’dir. Doğru seçenek C’dir; C ile D’nin ordinatları karıştırılmamalıdır.'],
 'Karenin sağ kenarının apsisini a sanmak a’nın bir uzunluk değil A’nın ordinatı olduğunu unutur; kenar a−b olarak hesaplanır.',
 'Koordinat farkı ve uzunluk','Aynı düşey doğru üzerindeki noktaların ordinat farkı, karenin yatay kenarının uzunluğuna eşittir.',
 'A=(0,a), B=(0,b) aynı biçimde bir karenin köşeleri; C, y=x/2 üzerinde ve a+b=16 ise D’nin koordinat toplamı kaçtır?',['16','18','20','22','24'],2,'b=(a−b)/2’den a=3b; b=4,a=12 olur. D=(8,12), toplam 20’dir.','C');
 add(307,'Dik doğrunun eksen kesenleri','Dik doğrular','AYT-mat',100,
 'Standart biçimde verilen doğrunun eğimini okuyup ona dik ve belirli noktadan geçen doğrunun iki eksen kesenini hesaplamayı ölçer.',
 ['2x−y=5 doğrusunun eğimi 2’dir; dik doğrunun eğimi −1/2 olur.','Nokta-eğim biçimi y−1=−(x+4)/2’dir; x koordinatındaki −4 işareti parantez içinde korunmalıdır.'],
 ['Denklem y=−x/2−1 olur. y=0 için x=−2 olduğundan a=−2’dir.','x=0 için b=−1 bulunur. a+b=−3 olduğundan doğru seçenek A’dır; iki kesen de negatiftir.'],
 'Dik eğimi yalnızca 1/2 almak işaret koşulunu bozar; dik iki sonlu eğimin çarpımı −1 olmalıdır.',
 'Nokta ve eğim','Bir doğru, eğimi ve üzerindeki tek noktayla belirlenir; eksen kesenleri bu denkleme sıfır konularak bulunur.',
 '(2,3)’ten geçen ve y=−2x+5’e dik olan doğrunun eksen kesenleri toplamı kaçtır?',['−4','−2','0','2','4'],1,'Dik eğim 1/2 olduğundan y=x/2+2’dir. Kesenler −4 ve 2, toplam −2 olur.','A');
 add(308,'Ağırlık ve diklik merkezinden alan','Üçgen merkezlerinin analitiği','AYT-mat',99,
 'Orijinden geçen yüksekliği ve ağırlık merkezi doğrultusunu birlikte kullanarak taban yüksekliğini ve yarı tabanı bulmayı ölçer.',
 ['Diklik merkezi H=(0,8) olduğundan orijinden çizilen yükseklik y eksenidir; karşı kenar yataydır.','Ağırlık merkezi (0,6), diğer köşeleri (u,9) ve (−u,9) yapar; taban yüksekliği 9’dur.'],
 ['H’ye giden (u,9) yüksekliğinin eğimi 1/u, orijinden (−u,9)’a giden kenarın eğimi −9/u’dur.','Diklikten −9/u²=−1, dolayısıyla |u|=3 çıkar. Taban 6 ve yükseklik 9 olduğundan alan 27’dir; doğru seçenek D’dir.'],
 'Diklik merkezinin ordinatı 8’i doğrudan üçgen yüksekliği almak yanlış olur; H iç noktadır, taban yüksekliği ağırlık merkezinden 9 bulunur.',
 'Eğimle diklik','İki merkezin ortak düşey doğrultusu şekli simetrik koordinatlarla kurar; dik eğimler taban uzunluğunu belirler.',
 'Bir köşesi orijin, ağırlık merkezi (0,4), diklik merkezi (0,4) olan üçgenin alanı kaçtır?',['6√3','12√3','18√3','24√3','36√3'],1,'Diğer köşeler (±u,6)’dır. Yükseklik dikliğinden u²=6·(6−4)=12; alan 6u=12√3’tür.','D');
 add(309,'Orta noktadan iki uçta bölge belirleme','İki nokta arası uzaklık','AYT-mat',99,
 'Eğimi bir olan doğru üzerinde uzunluğu verilen parçanın uçlarını orta noktanın iki yanında hesaplayıp koordinat işaretlerini incelemeyi ölçer.',
 ['y=x+2 üzerindeki bir parçanın eşit x ve y değişimleri vardır.','Orta nokta (−1,1) çevresinde uçlar (−1±t,1±t) yazılır; toplam uzaklık 2√2|t|’dir.'],
 ['2√2|t|=3 olduğundan |t|=3√2/4>1 bulunur.','Artı işaretli uçta her iki koordinat pozitif, eksi işaretli uçta her ikisi negatiftir. Uçlar I ve III. bölgededir; doğru seçenek D’dir.'],
 'Orta noktanın II. bölgede olması uçların da bu bölgede kalmasını gerektirmez; yarı parçanın her koordinattaki değişimi 1’i aşmaktadır.',
 'Vektörle öteleme','Orta noktadan zıt yönlü eşit vektörler uçları verir; uzaklık, bu vektörün büyüklüğünün iki katıdır.',
 'y=x doğrusu üzerindeki bir parçanın orta noktası (1,1), uzunluğu 4√2’dir. Uçlar hangi bölgelerdedir?',['I ve II','I ve III','II ve IV','İkisi de I','III ve IV'],1,'Yarı uzunluk 2√2 olduğundan koordinat değişimi 2’dir. Uçlar (3,3) ve (−1,−1), yani I ve III’tedir.','D');
 add(310,'Dik eğimlerin toplamından taban bulma','Doğrular ve üçgen alanı','AYT-mat',100,
 'Aynı noktada dik kesişen iki doğrunun eğim toplamını çarpım koşuluyla birleştirip x eksenindeki taban uzunluğunu bulmayı ölçer.',
 ['Dik doğruların eğimleri m ve n için mn=−1, soruda m+n=3/2’dir.','Bu iki sayının kök olduğu denklem t²−3t/2−1=0’dır; kökler 2 ve −1/2’dir.'],
 ['A=(3,4) üzerinden eğimi 2 olan doğru x eksenini x=1’de; eğimi −1/2 olan doğru x=11’de keser.','Taban |BC|=10, A’nın x eksenine uzaklığı 4’tür. Alan 10·4/2=20 olur; doğru seçenek B’dir.'],
 'Eğimlerin toplamını taban uzunluğu gibi kullanmak geometrik birimlere uymaz; önce iki doğrunun x kesenleri hesaplanmalıdır.',
 'Kökler ve katsayılar','Eğimlerin toplamı ve diklikten gelen çarpımı, ikinci derece denklem kurarak iki doğruyu ayrı ayrı belirler.',
 '(0,3)’te dik kesişen iki doğrunun eğimleri toplamı 0 ise x ekseniyle oluşturdukları üçgenin alanı kaçtır?',['3','6','9','12','18'],2,'Eğimler 1 ve −1’dir; x kesenleri −3 ve 3 olur. Taban 6, yükseklik 3, alan 9’dur.','B');
 add(311,'Ortak y keseni ve diklik koşulu','Dik doğrular','AYT-mat',100,
 'Denklemlerdeki parametreleri eğim çarpımı ve y eksenindeki ortak kesişim koşulundan ayırarak hesaplamayı ölçer.',
 ['İlk doğrunun eğimi 2/3, ikincinin eğimi 3/b’dir; b=0 ikinci doğruyu düşey yapar ve burada dikliği sağlamaz.','Diklik, (2/3)(3/b)=−1 olduğundan b=−2 verir.'],
 ['İkinci doğrunun y ekseni keseni −12/b=6’dır. Ortak kesişim y ekseninde olduğundan ilk doğrunun a/3 keseni de 6 olmalıdır.','a=18 bulunur. a+b=18−2=16 olduğundan doğru seçenek A’dır.'],
 'a ve b’yi doğrudan eğimler sanmak, denklemleri y yalnız bırakmadan okumaktır; katsayıların oranları alınmalıdır.',
 'İki bağımsız koşul','Diklik b’yi, aynı y ekseni kesişimi ise bundan sonra a’yı belirler; koşullar sırayla kullanılmalıdır.',
 'y=x+a ve by=2x−8 doğruları y ekseninde dik kesişiyorsa a+b kaçtır?',['0','1','2','3','4'],2,'Eğim çarpımı 2/b=−1’den b=−2 çıkar. Ortak ordinat −8/b=4 olduğundan a=4, toplam 2’dir.','A');
 add(312,'Kare merkezinden uzak köşeye geçme','Karenin analitik incelenmesi','AYT-mat',99,
 'Birinci bölgede eksenlere paralel karenin en uzak köşesinin merkezden iki koordinatta da yarım kenar ileride olduğunu kullanmayı ölçer.',
 ['Köşegenlerin kesişimi karenin merkezi (3,6)’dır. Kenar uzunluğu s ise sağ üst köşe (3+s/2,6+s/2)’dir.','Bütün köşeler birinci bölgede olduğundan orijine en uzak köşe sağ üst köşedir.'],
 ['Bu köşenin koordinat toplamı 9+s=14 olduğundan s=5 bulunur.','Karenin alanı s²=25’tir. Sol alt köşe (1/2,7/2) birinci bölgede kalır; çözüm şekil koşulunu sağlar. Doğru seçenek D’dir.'],
 'Toplamdaki artışı 2s almak, merkezden köşeye yatay ve düşey uzaklıkların s/2 olduğunu unutmak demektir.',
 'Simetri merkezi','Köşegen orta noktası, tüm köşelerin koordinatlarını tek uzunluk parametresiyle ifade etmeyi sağlar.',
 'Merkezi (4,7) olan eksenlere paralel birinci bölge karesinin en uzak köşesinin koordinat toplamı 17’dir. Alanı kaçtır?',['16','25','36','49','64'],2,'Sağ üst köşe toplamı 4+7+s=17’den s=6 bulunur. Alan 36’dır.','D');
 add(313,'Krokide uzaklık koşullarıyla yer eşleştirme','Koordinat ve uzaklık','AYT-mat',99,
 'Etiketsiz altı noktanın kurumlarını en büyük uzaklık ve iki eşit uzaklık koşuluyla belirleyip istenen uzunluk oranını hesaplamayı ölçer.',
 ['Sol üst köşe başlangıç, aşağı yön pozitif seçilirse noktalar (2,1),(5,1),(1,3),(3,3),(6,4),(2,6)’dır.','En büyük uzaklık karesi 34, (5,1) ile (2,6) arasındadır; bunlar hastane ve kütüphanedir.'],
 ['Eşit uzaklıklar kütüphaneyi (2,6), parkı (3,3), marketi (6,4), belediyeyi (2,1), okulu (1,3) olarak belirler.','Belediye–okul √5, market–kütüphane √20=2√5’tir. Oran 1/2 olur; doğru seçenek A’dır.'],
 'Şekilde yalnız yatay farkı saymak iki eğik uzaklıkta da düşey bileşeni kaybettirir; kareleri toplayarak gerçek uzaklık kullanılmalıdır.',
 'Pisagor ve eşit uzaklık','Kroki koşulları koordinat farklarının kareleriyle sınanır; ortak √5 çarpanı oranı sadeleştirir.',
 'A=(1,1), B=(2,3), C=(4,2), D=(6,6) ise |AB|/|CD| kaçtır?',['1/4','1/3','1/2','1','2'],2,'|AB|=√(1+4)=√5, |CD|=√(4+16)=2√5 olduğundan oran 1/2’dir.','A');
 add(314,'Daireyi dört eşit dilime bölen doğrular','Dik doğrular','AYT-mat',100,
 'Daire merkezinden geçen iki doğrunun dört bölgeyi eşitlemesinin diklik gerektirdiğini belirleyip nokta-eğim denklemini kurmayı ölçer.',
 ['Merkezden çıkan sektörlerin alanları merkez açılarıyla orantılıdır; dört eşit bölge için her açı 90° olmalıdır.','2x+y=12 doğrusunun eğimi −2 olduğundan d’nin eğimi 1/2’dir.'],
 ['d, A=(4,4)’ten geçer: y−4=(x−4)/2 yazılır.','Düzenlenirse 2y−8=x−4, yani x−2y=−4 bulunur. Bu, E seçeneğidir; A noktası denklemi de sağlar.'],
 'Yalnız merkezden geçmeyi yeterli saymak iki büyük ve iki küçük sektör oluşabileceğini gözden kaçırır; dört alanın eşitliği dik açı ister.',
 'Sektör alanı ve eğim','Eşit daire alanları açısal koşula, bu koşul da eğimlerin çarpımının −1 olmasına dönüştürülür.',
 'Merkezi (2,3) olan daireyi y=2x−1 ile birlikte dört eşit alana bölen doğrunun denklemi nedir?',['x+2y=8','2x+y=7','x−2y=−4','y=2x−1','x+y=5'],0,'Dik eğim −1/2’dir. y−3=−(x−2)/2 denklemi x+2y=8 verir.','E');
 add(315,'Eşit ağırlık merkezinden köşe farkı','Üçgenin ağırlık merkezi','AYT-mat',99,
 'İki üçgenin bilinmeyen köşelerini tek tek bulmadan, eşit ağırlık merkezinden aralarındaki sabit vektör farkını hesaplamayı ölçer.',
 ['Ağırlık merkezleri eşitse A+B+C=D+E+F vektörel toplamı sağlanır.','Dolayısıyla C−F=(D+E)−(A+B); bilinmeyen ortak merkezin koordinatları gerekli değildir.'],
 ['D+E=(7,19), A+B=(19,3) olduğundan C−F=(−12,16) bulunur.','C ile F arası uzaklık √(144+256)=√400=20’dir. Doğru seçenek E’dir; vektörün yönünü ters almak uzaklığı değiştirmez.'],
 'C ve F’nin ayrı ayrı bilinmediği için uzaklığın da belirlenemeyeceğini düşünmek, toplam eşitliğinin onların farkını sabitlediğini kaçırır.',
 'Vektör farkı','Ortak ağırlık merkezi iki koordinat toplamını eşitler; sabit fark, Öklid uzaklığı için yeterli bilgidir.',
 'A+B=(8,5), D+E=(11,9) ve ABC ile DEF’nin ağırlık merkezleri aynıysa |CF| kaçtır?',['3','4','5','6','7'],2,'C−F=(3,4) olur. Uzaklık √(3²+4²)=5’tir.','E');
 add(316,'Ortak köşeli iki kare için doğrusal sistem','Kare ve doğru denklemi','AYT-mat',100,
 'Şekildeki iki karenin doğru üzerinde bulunan farklı köşelerini kenar uzunluklarıyla ifade ederek iki bilinmeyenli sistem kurmayı ölçer.',
 ['Kırmızı kenar a, mavi kenar b seçilirse ortak köşe (a,b)’dir.','Doğru üzerindeki kırmızı köşe (a,a+b), mavi köşe (a+b,b)’dir; doğru 3x+2y=6 biçimindedir.'],
 ['İki köşeyi yerine koyunca 5a+2b=6 ve 3a+5b=6 elde edilir.','İlk denklemi 5, ikinciyi 2 ile çarpıp çıkarınca 19a=18 bulunur. Kırmızı kenar 18/19’dur; doğru seçenek E’dir.'],
 'Ortak köşeyi doğru üzerindeymiş gibi almak şekildeki üçüncü konumu yanlış okur; doğru her iki karenin sağ üst köşelerinden geçmektedir.',
 'Görselden denklem kurma','Eksenlere paralellik kare kenarlarını koordinat farklarına dönüştürür; ortak köşe iki modelin bağlantısını sağlar.',
 'Aynı yerleşimdeki karelerin sağ üst köşeleri x+y=5 üzerinde olsun. Kırmızı karenin kenarı kaçtır?',['1','4/3','5/3','2','5/2'],2,'Köşelerden 2a+b=5 ve a+2b=5 çıkar. a=b=5/3 bulunur.','E');
 add(317,'Üç doğruyla sınırlanan üçgenin alanı','Doğruların kesişimi','AYT-mat',100,
 'İki orijin doğrusunun üçüncü doğruyla kesişimlerini bulup üçgensel bölgenin alanını koordinatlarla hesaplamayı ölçer.',
 ['2x−y=0 ve x+2y=0 doğruları orijinde kesişir; eğimleri 2 ve −1/2’dir.','Üçüncü doğru x−8y+30=0’dır; iki ayrı yerine koyma diğer iki köşeyi verir.'],
 ['y=2x için −15x+30=0’dan (2,4); y=−x/2 için 5x+30=0’dan (−6,3) bulunur.','Alan |2·3−4·(−6)|/2=15’tir. Alternatif olarak dik kenar uzunlukları 2√5 ve 3√5 çarpılabilir. Doğru seçenek C’dir.'],
 'Üçüncü doğrunun eksen kesenleriyle alan hesaplamak farklı bir üçgen verir; sınırın diğer iki kenarı koordinat eksenleri değildir.',
 'Diklik ve determinant','İlk iki doğrunun dikliği geometrik alan hesabını, orijin köşesi ise determinant hesabını kolaylaştırır.',
 'y=x, y=−x ve x=4 doğrularının sınırladığı üçgenin alanı kaçtır?',['8','12','16','20','32'],2,'Köşeler (0,0),(4,4),(4,−4)’tür. Düşey taban 8, yatay yükseklik 4, alan 16 olur.','C');
 add(318,'Orta noktaları birleştiren doğrunun kesenleri','Doğru ve üçgen alanı','AYT-mat',100,
 'Verilen iki noktadan geçen doğrunun eksen kesenlerini bulup bunların üçgen kenarlarının yarıları olduğunu kullanmayı ölçer.',
 ['P=(6,−3), R=(−2,9) olduğundan doğrunun eğimi (9+3)/(−2−6)=−3/2’dir.','Denklem y=−3x/2+6; y keseni 6, x keseni 4’tür.'],
 ['Bu kesişimler OB ve OA’nın orta noktaları olduğundan |OB|=12, |OA|=8 bulunur.','Eksenler dik olduğu için alan 8·12/2=48’dir. Doğru seçenek C’dir; orta nokta üçgeninin alanı bunun dörtte biridir.'],
 '4 ve 6’yı doğrudan büyük üçgenin kenarları almak alanı dörtte birine indirir; her iki uzunluk da ikiyle çarpılmalıdır.',
 'Benzerlik ve orta taban','Orta noktalardan geçen çizgi, orijinli küçük üçgeni büyük üçgene 1/2 oranında benzer yapar.',
 'Bir eksen üçgeninin iki kenarının orta noktalarından geçen doğru x/3+y/5=1 ise büyük üçgenin alanı kaçtır?',['15','20','30','45','60'],2,'Orta nokta kesenleri 3 ve 5 olduğundan büyük kenarlar 6 ve 10’dur. Alan 6·10/2=30 olur.','C');
 add(319,'Eşkenar üçgenden eğim ve kesen','Analitik düzlemde eşkenar üçgen','AYT-mat',100,
 'x eksenine dayalı eşkenar üçgenin alanından kenarı bulup pozitif eğimli kenarın y kesenini hesaplamayı ölçer.',
 ['Eşkenar üçgen alanı s²√3/4’tür; verilen 9√3 alanı s=6 verir.','Kenar eğimleri ±√3’tür. a pozitif olduğundan a=√3; diğer taban ucu x=−6’dır.'],
 ['Orijinden eğimi −√3 olan kenar, üçgenin tepe noktasına (−3,3√3) gider.','y=√3x+b’ye bu nokta konursa b=6√3 çıkar. ab=√3·6√3=18’dir; doğru seçenek A’dır.'],
 'Pozitif b nedeniyle tepeyi birinci bölgede varsaymak −√3 eğimli orijin kenarıyla çelişir; eşkenar bölge y ekseninin solundadır.',
 'Trigonometri ve doğru eğimi','Tabanla 60° yapan kenarın eğimi tan60°’dir; alan bilgisi doğru denkleminin sabit terimini belirler.',
 'Aynı iki eğimle oluşan, x ekseni tabanlı eşkenar üçgenin alanı 4√3 ise pozitif eğimli kenarın a·b çarpımı kaçtır?',['6','8','10','12','16'],3,'Kenar 4’tür. a=√3 ve b=4√3 olduğundan ab=12’dir.','A');
 add(320,'Eksen kesmelerini işaret değişimine çevirme','Koordinat bölgeleri','AYT-mat',99,
 'Bir doğru parçasının hangi eksenleri kestiğini, uç koordinatların işaret değişimi olarak izleyerek beş noktanın bölgelerini belirlemeyi ölçer.',
 ['Yalnız x eksenini kesmede y işareti değişir, x işareti aynı kalır.','Her iki ekseni kesen parçada iki koordinatın da işareti değişir; yalnız y ekseninde ise sadece x işareti değişir.'],
 ['A=(+,+) iken AB’den B=(+,−), BC’den C=(−,+) bulunur.','CD yalnız y eksenini kestiğinden D=(+,+); DE her ikisini kestiğinden E=(−,−) olur. A ile D aynı I. bölgededir; doğru seçenek B’dir.'],
 'x eksenini kesmeyi x koordinatının işaret değiştirmesi sanmak eksen adını değişen koordinatla karıştırır; x ekseninde sıfırlanan ordinattır.',
 'Doğrusal ara değer','Bir parçanın koordinatları uç değerler arasında doğrusal değişir; sıfırdan geçişler işaretlerin zıtlığıyla belirlenir.',
 'P II. bölgede; PQ yalnız x eksenini, QR yalnız y eksenini kesiyor. R hangi bölgededir?',['I','II','III','IV','Belirlenemez'],3,'P=(−,+) olduğundan Q=(−,−), ardından R=(+,−) olur. R IV. bölgededir.','B');
 add(321,'Paralel doğruların eksen aralıklarından dik uzaklık','Paralel doğrular','AYT-mat',100,
 'Paralel doğruların eksen kesen farklarını ortak eğime ve normal doğrultudaki uzaklığa dönüştürmeyi ölçer.',
 ['Doğrular y=mx+c₁ ve y=mx+c₂ yazılırsa y kesen farkı |c₁−c₂|=40’tır.','x kesen farkı |c₁−c₂|/|m|=30 olduğundan |m|=4/3 bulunur.'],
 ['Paralel doğruların dik uzaklığı |c₁−c₂|/√(m²+1) formülüyle hesaplanır.','Uzaklık 40/√(16/9+1)=40/(5/3)=24’tür. Eğimin işareti uzaklık sonucunu etkilemez; doğru seçenek A’dır.'],
 '30 ve 40’ı dik kenar sayıp 50’yi cevaplamak eksenler arası yardımcı üçgenin hipotenüsünü verir; istenen bu üçgendeki hipotenüse ait yüksekliktir.',
 'Dik üçgende yükseklik','30–40–50 yardımcı üçgeninde alan eşitliği de 30·40/50=24 dik uzaklığını verir.',
 'İki paralel doğrunun x kesen farkı 6, y kesen farkı 8 ise aralarındaki uzaklık kaçtır?',['12/5','18/5','24/5','6','8'],2,'Eğim mutlak değeri 4/3’tür. Uzaklık 8/(5/3)=24/5 bulunur.','A');
 add(322,'Tek noktada kesişme koşuluyla kareyi yerleştirme','Doğru ve çokgen konumu','AYT-mat',100,
 'Orijinden geçen doğrunun dikdörtgene tek noktada temasını ve birim kareye farklı bir köşede temasını birlikte değerlendirerek kare konumunu belirlemeyi ölçer.',
 ['Alanı 1 olan karenin kenarı 1’dir. Dikdörtgene tek noktada değen orijin doğrusu sol üst D=(4,2)’den geçer: y=x/2.','x eksenindeki kenar doğrusu dikdörtgene bir kenar boyunca değeceğinden tek nokta koşulunu sağlamaz.'],
 ['Üst uzun kenara dışarıdan eklenen karenin düşey aralığı [2,3]’tür. Doğru, karenin sol üst köşesine değerse bu köşe (6,3) olur.','Kare [6,7]×[2,3] konumundadır. En uzak köşe (7,3), koordinat toplamı 10’dur; doğru seçenek A’dır.'],
 'Kareyi D köşesine değecek biçimde yerleştirmek iki temas noktasının farklı olması şartını bozar; üst temasın (6,3) olması gerekir.',
 'Destek doğrusu','Tek nokta kesişimi çokgenin içinden geçen bir kesen değil, bir köşedeki destek doğrusu gerektirir.',
 'y=x/2 doğrusu [8,9]×[u,u+1] birim karesine yalnız sol üst köşede değiyorsa u kaçtır?',['1','2','3','4','5'],2,'Sol üst köşe (8,u+1) doğrudaysa u+1=4 olur. Diğer kare noktaları doğrunun altında kaldığından u=3’tür.','A');
 add(323,'Çemberlerin orijine en yakın noktaları','Çemberin analitik incelenmesi','AYT-mat',126,
 'Merkezleri ve ortak teğet noktası verilen çemberlerin yarıçaplarını hesaplayıp orijine en yakın çember noktalarının yerini belirlemeyi ölçer.',
 ['(12,0) merkezinden (4,6)’ya uzaklık √(64+36)=10; (0,9) merkezinden aynı noktaya uzaklık √(16+9)=5’tir.','Orijin her iki çemberin dışındadır; en yakın noktalar merkez–orijin doğrularında, merkeze yarıçap kadar yaklaşarak bulunur.'],
 ['İlk çemberin en yakın noktası (12−10,0)=(2,0), ikincininki (0,9−5)=(0,4)’tür.','Bu iki noktanın uzaklığı √(2²+4²)=√20=2√5’tir. Doğru seçenek D’dir. Merkezler arası 15 uzaklık da dıştan teğetliği doğrular.'],
 'Ortak (4,6) noktasını iki çemberin orijine en yakını sanmak merkez–orijin doğrultusunu dikkate almaz; ortak nokta farklı bir geometrik özelliktir.',
 'En kısa uzaklık','Bir dış noktadan çembere en kısa yol, o nokta ve merkezle doğrusal olan yarıçap üzerinde gerçekleşir.',
 'Merkezleri (8,0),(0,7), yarıçapları sırasıyla 5 ve 3 olan çemberlerin orijine en yakın noktaları arası uzaklık kaçtır?',['3','4','5','6','7'],2,'En yakın noktalar (3,0),(0,4) olur. Aralarındaki uzaklık 5’tir.','D');
 add(324,'Çap doğrusu ve eksen teğetliğinden yarıçap','Çemberde kiriş','AYT-mat',126,
 'Çemberi eşit parçalara ayıran doğrunun merkezden geçtiğini, x eksenine tek temasın yarıçap koşulu olduğunu kullanmayı ölçer.',
 ['Merkez (h,k) ise x+y=4 doğrusunda bulunduğundan h+k=4’tür.','x eksenine teğetlik r=|k|, y eksenindeki 4 birimlik kirişin yarısı ise 2’dir.'],
 ['Kirişe merkezden indirilen dikmeyle r²−h²=4 olur. r²=k² olduğundan (k−h)(k+h)=4 çıkar.','k+h=4 ile k−h=1; buradan k=5/2, h=3/2 ve r=5/2’dir. Çevre 5π olur; doğru seçenek B’dir.'],
 'y eksenindeki 4 birimlik kirişi çap kabul etmek merkez y ekseninde değilken geçersizdir; merkezden kirişe yatay uzaklık h’dir.',
 'Pisagor ve tam kare farkı','Yarı kiriş üçgeni k²−h² bağıntısını verir; merkezin doğru üzerindeki konumu çarpanı bilinen bir denkleme dönüştürür.',
 'Merkezi x+y=5 üzerinde, x eksenine teğet bir çember y ekseninde 6 uzunluğunda kiriş oluşturuyor. Yarıçap kaçtır?',['13/5','3','17/5','4','5'],2,'k+h=5 ve k²−h²=9’dan k−h=9/5 bulunur. r=k=17/5’tir.','B');
 add(325,'İki kesişim için merkez doğru uzaklığı','Doğru ve çember','AYT-mat',127,
 'Genel çember denklemini merkez-yarıçap biçimine getirip doğrunun iki farklı kesişim koşulunu sıkı eşitsizlikle yazmayı ölçer.',
 ['Denklem (x−13)²+y²=25 olduğundan merkez (13,0), yarıçap 5’tir.','y=mx doğrusunun merkeze uzaklığı 13|m|/√(m²+1)’dir; iki kesişim için bu değer 5’ten küçük olmalıdır.'],
 ['Karesi alınınca 169m²<25(m²+1), yani 144m²<25 elde edilir.','Böylece −5/12<m<5/12 bulunur. Uçlarda teğetlik oluştuğundan uçlar alınmaz; doğru aralık D seçeneğidir.'],
 'Uç noktaları kapalı yazmak iki ayrı noktayı tek teğet noktaya indirir; kesişim sayısı eşitliğin dahil edilip edilmeyeceğini belirler.',
 'Diskriminant','y=mx yerine konulduğunda oluşan ikinci derece denklemin pozitif diskriminantı aynı açık aralığı verir.',
 'y=mx, (x−5)²+y²=9 çemberini iki noktada kesiyorsa m hangi aralıktadır?',['(−1/2,1/2)','(−3/4,3/4)','[−3/4,3/4]','(−4/3,4/3)','(−3,3)'],1,'25m²<9(m²+1) koşulu 16m²<9 verir. Aralık (−3/4,3/4)’tür.','D');
 add(326,'İki eksene teğet çemberlerin yarıçap toplamı','Çember denklemi','AYT-mat',126,
 'Birinci bölgede iki eksene teğet çemberin merkezini (r,r) yazarak verilen noktadan geçen iki çemberi tek ikinci derece denklemle bulmayı ölçer.',
 ['Her iki eksene teğet birinci bölge çemberinde merkez (r,r), yarıçap r>0’dır.','A=(1,2) noktası çember üzerinde olduğundan (1−r)²+(2−r)²=r² sağlanır.'],
 ['Açılım r²−6r+5=0, yani (r−1)(r−5)=0 verir. İki farklı yarıçap 1 ve 5’tir.','İstenen yarıçaplar toplamı 6’dır; doğru seçenek B’dir. Köklerin ikisi de pozitif olduğundan eksenlere teğetlik ve bölge koşullarına uygundur.'],
 'Merkezi (r,0) almak yalnız bir eksenle ilgili yerleşimi karşılar; iki eksene teğetlik her iki merkez koordinatının r olmasını gerektirir.',
 'Kökler toplamı','Yarıçaplar aynı ikinci derece denklemin kökleridir; toplam, kökleri tek tek hesaplamadan da 6 okunabilir.',
 'Birinci bölgede iki eksene teğet olup (2,3)’ten geçen iki çemberin yarıçapları toplamı kaçtır?',['5','6','8','10','13'],3,'(2−r)²+(3−r)²=r² eşitliği r²−10r+13=0 verir. İki pozitif kökün toplamı 10’dur.','B');
 add(327,'İç bölge koşulundan yarıçapa sıkı alt sınır','Teğet çember','AYT-mat',128,
 'Teğet noktasından çizilen normale merkez yerleştirip A’nın iç bölgede bulunmasını uzaklık eşitsizliği olarak kurmayı ölçer.',
 ['y=x’e B=(7,7)’de teğet çemberin merkezi (7+t,7−t) biçimindedir; r=√2|t| olur.','A=(11,9)’un merkez uzaklığının karesi (4−t)²+(2+t)²=20−4t+2t²’dir.'],
 ['İç bölge için 20−4t+2t²<2t², dolayısıyla t>5 gerekir. Merkez doğrunun A tarafında kalır.','r>5√2≈7,071 olduğundan alabileceği en küçük tam sayı 8’dir. Bu değer t=4√2>5 ile gerçekleşir; doğru seçenek B’dir.'],
 'A’nın çemberin üzerinde olduğunu varsayıp r=5√2 demek “iç bölge” ifadesindeki sıkı eşitsizliği kaybettirir; ayrıca sonuç bir tam sayıya yuvarlanarak aranır.',
 'Nokta doğru uzaklığı','Merkez teğet doğrultuya dik bir doğru üzerinde hareket eder; noktanın içeride olması bu hareketin alt sınırını belirler.',
 'y=x’e orijinde teğet bir çember (3,1)’i içinde taşıyor. Yarıçapının en küçük tam sayı değeri kaçtır?',['2','3','4','5','6'],2,'Merkez (t,−t), r=√2|t| olsun. (3−t)²+(1+t)²<2t²’den t>5/2; r>5√2/2≈3,536 çıkar. En küçük tam sayı 4’tür.','B');
 add(328,'Üç paralel doğruyla çember yarıçapı aralığı','Doğru çember konumu','AYT-mat',127,
 'Bir teğet, bir kesen ve bir dış doğru bilgisini ortak normal eksen üzerindeki uzaklık aralıklarıyla birlikte yorumlamayı ölçer.',
 ['q=(3y−4x)/5 normal koordinatında doğrular sırasıyla 138/5,18/5,3/5 konumundadır.','Merkezin normal koordinatı c ise teğetlik r=|c−138/5|; kesenlik |c−18/5|<r, dışlık |c−3/5|>r gerektirir.'],
 ['Kesen koşulu c<78/5, dış doğru koşulu c>141/10 verir; dolayısıyla 14,1<c<15,6’dır.','Merkez ilk doğrunun altında olduğundan r=27,6−c, yani 12<r<13,5 olur. Seçeneklerden yalnız 13 mümkündür; doğru seçenek B’dir.'],
 'Doğruların sabit terim farklarını dik uzaklık sanmak eğim normalleştirmesini atlar; tüm farklar √(1+16/9)=5/3’e bölünmelidir.',
 'Mutlak değer eşitsizliği','Paralel doğruların çemberle farklı kesişim sayıları merkez ve yarıçap için ortak bir açık aralık oluşturur.',
 'y=10’a teğet, y=2’yi iki noktada kesen ve y=0’la kesişmeyen çemberin yarıçapı hangi aralıktadır?',['(0,2)','(2,4)','(4,5)','(5,6)','(6,10)'],2,'Merkez ordinatı k için r=10−k; kesenlik k<6, dışlık k>5 verir. Böylece 4<r<5’tir.','B');
 add(329,'Dik çevre açıdan çap doğrusunu belirleme','Çemberin analitik incelenmesi','AYT-mat',126,
 'Dik çevre açının gördüğü kirişin çap olduğunu kullanıp merkez koordinatlarından çap doğrusunun eğimini ve verilen noktadan çember parametresini bulmayı ölçer.',
 ['MEB derlemesinde kapalı kutu olan koşul, resmî 2025 AYT matematik39’da m(BÂC)=90°’dir.','A=(4,1) denkleme konursa n=16+1−8+6=15; çember (x−1)²+(y+3)²=25 olur.'],
 ['Dik çevre açı nedeniyle BC çaptır; B ve C’yi taşıyan y=mx, merkez (1,−3)’ten geçmelidir.','−3=m·1’den m=−3 bulunur. m+n=−3+15=12 olduğundan doğru seçenek E’dir. Resmî tamamlama olmadan yalnız basılı metin m’yi belirlemez.'],
 'BC’yi rastgele bir kiriş kabul etmek eğimi serbest bırakır; kaybolmuş dik açı koşulu çözümü tekleştiren asıl bilgidir.',
 'Thales teoremi','Çevre açının 90° olması çapı belirler ve geometrik koşulu doğrunun merkezden geçmesi denklemine dönüştürür.',
 'Merkezi (2,−4) olan çemberde A,B,C çember üzerinde ve BÂC=90°’dir. BC doğrusu orijinden geçiyorsa eğimi kaçtır?',['−4','−2','−1','1','2'],1,'BC çap olduğundan merkez (2,−4)’ten geçer. Orijinle merkez arasındaki eğim −4/2=−2’dir.','E');
 all['q-ayt-matematik-329'].note='Derlemede m(BÂC)=90° koşulu gri eksik-görsel kutusudur. Koşul resmî ÖSYM 2025 AYT matematik 39, basılı34 üzerinden doğrulandı: https://dokuman.osym.gov.tr/pdfdokuman/2025/yks/tsk/yks_ayt_2025_kitapcik_st12.pdf';
 add(330,'Ötelemeyle korunan kirişten merkezi bulma','Çemberde öteleme','AYT-mat',126,
 'Yatay öteleme sonrası aynı y ekseni kirişinin korunmasını merkez apsislerinin zıtlığına dönüştürüp kiriş uzunluğunu hesaplamayı ölçer.',
 ['Beş birim aşağı ötelenince merkez x eksenine geliyorsa başlangıç merkezinin ordinatı 5’tir.','x eksenine teğetlik yarıçapı 5 yapar; altı birim sola kayınca merkez apsisi h−6 olur.'],
 ['Aynı y ekseni kesişimleri için h²=(h−6)², buradan h=3 bulunur.','Merkezden y eksenine uzaklık 3’tür. Yarı kiriş √(5²−3²)=4, tam kiriş 8 olur; doğru seçenek D’dir.'],
 'Yatay kaymanın 6 birimini merkez–y ekseni uzaklığı sanmak iki simetrik merkez arasındaki mesafeyi tek taraf uzaklığıyla karıştırır; uzaklık bunun yarısıdır.',
 'Simetri ve Pisagor','Aynı kiriş, merkezlerin y eksenine göre simetrisini gerektirir; yarıçapla yarı kiriş bir dik üçgen oluşturur.',
 'Yarıçapı 13 olan çember 10 birim sola ötelenince y eksenini aynı noktalarda kesiyor. Bu kirişin uzunluğu kaçtır?',['10','12','20','24','26'],3,'Merkez apsisi 5 olur. Yarı kiriş √(169−25)=12; tam kiriş 24’tür.','D');
 add(331,'Dönme yansıma bileşkesinin sabit noktaları','Dönüşüm geometrisi','AYT-mat',109,
 'Araya yansıma girdiğinde zıt yönlü dönmelerin birbirini doğrudan götürmediğini hesaplayıp bileşke dönüşümün sabit köşelerini bulmayı ölçer.',
 ['45° saat yönünün tersine dönmede (x,y), ((x−y)/√2,(x+y)/√2) olur.','y ekseni yansıması ilk koordinatın işaretini değiştirir; son 45° saat yönü dönüşü uygulanınca sonuç (y,x)’tir.'],
 ['Bileşke y=x doğrusuna göre yansımadır; sabit kalma koşulu x=y’dir.','A=(−1,−1) ve C=(1,1) bu koşulu sağlar. B ve D yer değiştirir; koordinatları değişmeyenler A ile C, yani B seçeneğidir.'],
 'İlk ve son dönmeler zıt diye onları iptal etmek aradaki yansımanın dönme eksenini değiştirdiğini yok sayar; işlem sırası korunmalıdır.',
 'Bileşke dönüşüm','Dönme–yansıma–ters dönme, yansıma doğrusunu başka doğrultuya taşır; sabit noktalar yeni yansıma doğrusu üzerindedir.',
 '(3,1) noktasına aynı üç dönüşüm uygulanırsa sonuç nedir?',['(−3,1)','(1,3)','(3,−1)','(−1,−3)','(−3,−1)'],1,'Bileşke (x,y)→(y,x) olduğundan görüntü (1,3)’tür.','B');
 add(332,'Dönme ve ötelemenin sabit noktası','Dönüşüm geometrisi','AYT-mat',109,
 '90° dönme kuralıyla öteleme vektörünü sırayla uygulayıp başlangıç noktasına dönme koşulundan iki koordinatı çözmeyi ölçer.',
 ['Orijin çevresinde 90° saat yönünün tersine dönme (a,b)→(−b,a) kuralındadır.','Ardından (3,1) kadar öteleme sonucu (3−b,a+1) elde edilir.'],
 ['Başlangıçla eşitleme a=3−b, b=a+1 verir; böylece a+b=3 ve b−a=1 olur.','Sistemden a=1,b=2 bulunur. İstenen ab=2 olduğundan doğru seçenek C’dir; görüntü (−2,1)+(3,1)=(1,2) ile kontrol edilir.'],
 'Ötelemeyi dönmeden önce uygulamak farklı sabit nokta üretir; dönme vektörünün yönünü de değiştirdiğinden dönüşüm sırası önemlidir.',
 'Doğrusal denklem sistemi','Dönüşümün sabit noktası, görüntü koordinatlarının başlangıç koordinatlarına eşitlendiği iki denklemin ortak çözümüdür.',
 '90° saat yönünün tersine dönüşten sonra (4,2) kadar ötelenince kendisine gelen noktanın koordinat toplamı kaçtır?',['2','3','4','5','6'],2,'a=4−b,b=a+2 olduğundan a=1,b=3 çıkar. Koordinat toplamı 4’tür.','C');
 add(333,'Ötelemenin oluşturduğu paralelkenar alanı','Öteleme ve alan','AYT-mat',109,
 'Aynı vektörle ötelenen iki noktanın oluşturduğu dörtgenin paralelkenar olduğunu belirleyip yatay taban ve düşey yüksekliğini kullanmayı ölçer.',
 ['Ötelemeden D=(5,7), C=(2,4) bulunur; AD ve BC yatay, uzunlukları 3’tür.','AB ve DC de aynı vektörle ilişkili olduğundan ABCD bir paralelkenardır; yükseklik 7−4=3’tür.'],
 ['Yatay taban BC=3, bu tabana A’nın dik uzaklığı 3 olduğundan alan 3·3=9’dur.','AB=3√2 uzunluğunu yükseklik sanmaya gerek yoktur; eğik kenar ile tabana dik uzaklık farklıdır. Doğru seçenek A’dır.'],
 'Dörtgeni bir dikdörtgen varsayıp eğik AB uzunluğuyla çarpmak fazla alan verir; öteleme paralelliği sağlar, dikliği sağlamaz.',
 'Vektör ve alan','Öteleme vektörü tabanı, başlangıç noktalarının düşey farkı ise bu tabana ait yüksekliği oluşturur.',
 '(1,2) ve (4,6) noktaları 5 birim sağa ötelenerek bir paralelkenar oluşturuyor. Alan kaçtır?',['10','15','20','25','30'],2,'Yatay taban 5, düşey yükseklik 6−2=4 olduğundan alan 20’dir.','A');
 add(334,'Yansıma ekseni üzerindeki noktanın eşit uzaklığı','Yansımada uzaklık','AYT-mat',109,
 'Yansıma doğrusunun bilinen bir noktadan geçmesini o noktanın asıl ve görüntü noktalarına eşit uzaklıkta olması koşuluna dönüştürmeyi ölçer.',
 ['Yansıma ekseni üzerindeki T=(1,0), P=(4,4) ve görüntüsü Q=(a,0)’a eşit uzaklıktadır.','TP=√((4−1)²+4²)=5 olduğundan TQ=|a−1|=5 olmalıdır.'],
 ['a−1=5 veya a−1=−5’ten a=6 ve a=−4 elde edilir.','Her iki Q için PQ’nun orta dikmesi T’den geçer; iki değer de gerçek bir yansıma ekseni üretir. Çarpımları −24’tür; doğru seçenek A’dır.'],
 'Yansıma doğrusunu x ekseni varsaymak yalnız verilen (1,0) noktasını eksenin tamamı gibi okumaktır; doğrunun eğimi serbesttir.',
 'Orta dikme','Bir nokta ile yansımasının orta dikmesi yansıma eksenidir; eksen üzerindeki eşit uzaklık koşulu yeterlidir.',
 '(3,4)’ün (0,0)’dan geçen bir doğruya göre görüntüsü (a,0) ise a’nın olası değerlerinin çarpımı kaçtır?',['−25','−16','−9','16','25'],0,'Orijin yansımada sabittir; görüntünün orijine uzaklığı 5 olmalıdır. a=±5, çarpım −25’tir.','A');
 add(335,'Yansıma ve ötelemede ortak eşkenar bölge','Dönüşüm ve benzerlik','AYT-mat',109,
 'Şekildeki yansıma-öteleme dönüşümünün taban uçlarını eşleştirip iki eşkenar üçgenin örtüşme tabanını büyük kenarla ilişkilendirmeyi ölçer.',
 ['Dönüşüm x→9−x’tir. Şekilde orijine gelen köşe B olduğundan B’nin apsisi 9’dur.','Büyük eşkenar üçgenin kenarı s ise ilk taban [9−s,9], görüntü tabanı [0,s] aralığındadır.'],
 ['Ortak eşkenar bölgenin tabanı [9−s,s] olup uzunluğu 2s−9’dur; verilen küçük kenar 1’e eşittir.','2s−9=1’den s=5 çıkar. ABC çevresi 3s=15’tir; doğru seçenek C’dir. Aynı eğimli kenarlar ortak bölgenin de eşkenar olmasını sağlar.'],
 '9 birim ötelemeyi üçgen kenarı sanmak başlangıç tabanının orijinden başlamadığını gözden kaçırır; uçlar dönüşüm kuralıyla eşlenmelidir.',
 'Aralıkların kesişimi','Geometrik örtüşmenin tabanı, iki taban aralığının ortak kısmıdır; eşkenar yapı bu uzunluğu küçük üçgenin kenarı yapar.',
 'Aynı yerleşimde x→13−x dönüşümüyle oluşan iki eşkenar üçgenin ortak kenarı 3 ise büyük üçgenin çevresi kaçtır?',['18','21','24','27','30'],2,'Büyük kenar s için 2s−13=3 olur. s=8 ve çevre 24’tür.','C');
 add(336,'Dönme açılarından ikizkenar levhanın yönü','Dönme ve üçgende açılar','AYT-mat',109,
 'Dönme bilgilerinden kenar yönlerini bulup ikizkenarlıkla kırmızı kenarın yatay olma açısını hesaplamayı ölçer.',
 ['Siyah kenarın yukarı yönü yatayla 75°, mavi kenarın çividen sağ köşeye yönü yatayla −40° yapar.','Çivide siyahın aşağı yönü 255°, mavinin yönü 320° olduğundan aralarındaki iç açı 65°’dir.'],
 ['Mavi ve kırmızı eşit kenarlar olduğundan siyah tabanın iki ucundaki açılar 65°’tir.','Sol alt köşede siyahın yönü 75° olduğuna göre kırmızı kenarın yatayla açısı 75−65=10°’dir. Saat yönünde ilk paralellik x=10° verir; doğru seçenek B’dir.'],
 '75° ile 40°’yi çıkarmak zıt ışın yönlerini karıştırır; çivide siyahın aşağı yönü kullanılmalıdır.',
 'Yön açısı ve ikizkenarlık','Dönmeler doğrultu bilgisini verir; eşit kenarlar bu doğrultuları birbirine bağlayan eşit taban açılarını sağlar.',
 'Aynı yerleşimde siyah 80° saat yönü, mavi 40° ters yönde dönünce yataylaşıyor. Kırmızı ilk kaç derece saat yönünde dönünce yataylaşır?',['5','10','15','20','25'],3,'Siyahın aşağı yönü 260°, mavinin yönü 320°; taban açısı 60°’tir. Kırmızı yönü 80−60=20° olduğundan saat yönü dönme 20°’dir.','B');
 add(337,'Nokta ve eksen simetrilerinden parametre','Simetri dönüşümleri','AYT-mat',109,
 'Bir noktaya göre merkezi simetri ile y ekseni yansımasının farklı koordinat kurallarını kullanıp aynı doğru üzerindeki iki görüntüden a ve b’yi bulmayı ölçer.',
 ['B=(3,0)’a göre A=(a,b)’nin simetriği C=(6−a,−b)’dir.','y eksenine göre görüntü D=(−a,b)’dir; her ikisi y=−x−1 doğrusunu sağlamalıdır.'],
 ['C’den −b=−(6−a)−1=a−7, dolayısıyla a+b=7 bulunur.','D’den b=a−1 elde edilir; a=4,b=3 ile görüntüler (2,−3),(−4,3) doğru üzerinde doğrulanır. İstenen toplam 7’dir; doğru seçenek A’dır.'],
 'B’ye göre simetride yalnız apsisin işaretini değiştirmek merkezî simetriyi eksen yansımasıyla karıştırır; iki koordinatta da merkezden ters uzaklık alınır.',
 'Orta nokta bağıntısı','Merkezî simetride B, A ile C’nin orta noktasıdır; bu ilişki 6−a ve −b ifadelerini üretir.',
 'A=(a,b)’nin (2,0)’a göre simetriği y=−x+1 üzerinde ise a+b kaçtır?',['1','2','3','4','5'],2,'Görüntü (4−a,−b)’dir. −b=−(4−a)+1=a−3 eşitliği a+b=3 verir.','A');
 add(338,'İki ötelemenin doğru denklemine etkisi','Öteleme ve doğru','AYT-mat',109,
 'Bilinmeyen başlangıç noktasının yatay ve düşey ötelenmelerini doğru denklemine ayrı ayrı yazarak koordinatları bulmadan gerekli düşey kaymayı hesaplamayı ölçer.',
 ['A=(u,v) olsun. (u−15,v) doğru üzerindeyse 4u−3v+24=60’tır.','Yukarı k kadar öteleme (u,v+k) verir; doğru ifadesinin değeri 60−3k olur.'],
 ['Yeni noktanın d üzerinde olması için 60−3k=0 yazılır ve k=20 bulunur.','Yukarı yön pozitif olduğundan bulunan değer istenen yönle uyumludur. Başlangıç koordinatlarına ayrıca ihtiyaç yoktur; doğru seçenek D’dir.'],
 '15’i doğrudan yukarı kayma olarak taşımak yatay ve düşey katsayıların 4 ve −3 olmasını gözden kaçırır; denklemdeki değişimler eşitlenmelidir.',
 'Doğru eğimi','Eğim 4/3 olduğundan doğru üzerinde 15 birim sağa gitmeye karşılık 20 birim yukarı gidilir; bu geometrik yorum aynı sonucu verir.',
 'A’nın 12 birim sola ötelenmişi 2x−3y+6=0 üzerindedir. A kaç birim yukarı ötelenirse bu doğruya gelir?',['4','6','8','10','12'],2,'Başlangıç doğru ifadesi 24’tür. Yukarı k öteleme bunu 3k azaltır; 24−3k=0’dan k=8 bulunur.','D');
 add(339,'Dikdörtgende iki yansıma ekseni','Simetri ve dikdörtgen','AYT-mat',109,
 'Bir köşenin iki ardışık eksen yansımasından dikdörtgen yüksekliğini, çevreden genişliğini ve simetri ekseninin apsisini hesaplamayı ölçer.',
 ['A=(a,5)’in x=b’ye göre görüntüsü B=(13,5)’tir; böylece 2b−a=13 olur.','B’nin y=6’ya göre görüntüsü C=(13,12−5)=(13,7)’dir; c=7 ve yükseklik 2’dir.'],
 ['Çevre 20 olduğundan genişlik+yükseklik=10; genişlik 8 bulunur. Şekilde a<13, dolayısıyla 13−a=8’den a=5’tir.','Simetri ekseni b=(5+13)/2=9’dur. a+b+c=5+9+7=21 bulunur; doğru seçenek E’dir.'],
 'y=6’yı C’nin ordinatı sanmak yansıma eksenini görüntü noktasıyla karıştırır; 5 ile c’nin ortalaması 6 olmalıdır.',
 'Orta nokta ve çevre','Simetri eksenleri karşılıklı koordinatların ortalamalarını verir; çevre bilinmeyen yatay kenarı tekleştirir.',
 'A=(a,2), B=(12,2), C=(12,c) dikdörtgeninde AB’nin simetri ekseni x=8, BC’ninki y=5 ise çevre kaçtır?',['20','24','28','32','36'],2,'a=16−12=4, c=10−2=8 olur. Genişlik 8, yükseklik 6, çevre 28’dir.','E');
 add(340,'Birim küplerin köşelerinde uzaklık kısıtı','Uzayda uzaklık','TYT-mat',154,
 'Yüzlerinden yapıştırılan birim küplerin ortak tam sayı koordinat sistemine yerleştiğini kullanarak köşe uzaklıklarının karelerini sınıflandırmayı ölçer.',
 ['Üç küp ya doğrusal bir 3×1×1 prizma ya da L biçimli yerleşim oluşturur; tüm köşelerin koordinatları tam sayıdır.','İki köşe uzaklığının karesi üç tam sayı koordinat farkının kareleri toplamıdır.'],
 ['7, üç tam sayı karesinin toplamı olamaz: kullanılabilecek kareler 0,1,4’tür; 4+1+1=6’dan sonra 7 elde edilemez.','Diğerleri mümkündür: L yerleşiminde (2,2,0) farkı √8; doğrusal yerleşimde (3,0,0),(3,1,0),(3,1,1) farkları 3,√10,√11 verir. Olamayan √7, A seçeneğidir.'],
 'Cismin yalnız uzay köşegenini incelemek seçilen iki köşenin herhangi bir çift olabileceğini kaçırır; tüm uygun koordinat farkları değerlendirilmelidir.',
 'Üç boyutlu Pisagor','Köşe farklarının tam sayı olması uzunlukların karelerine aritmetik sınırlama getirir; geometri imkânsızlık hesabına dönüşür.',
 '2×1×1 dikdörtgenler prizmasının iki köşesi arasındaki uzaklık hangisi olamaz?',['1','√2','2','√5','√7'],4,'Koordinat farkları en çok (2,1,1)’dir. En büyük uzaklık √6 olduğundan √7 mümkün değildir.','A');
 add(341,'Kesilmiş daire yayından koni yarıçapı','Dik dairesel koni','AYT-mat',135,
 'Koniye dönüştürülen daire diliminin yarıçapının ana doğru, yayının ise taban çevresi olduğunu ayırarak yüksekliği hesaplamayı ölçer.',
 ['Başlangıç dairesinin yarıçapı 8 olduğundan oluşan koninin ana doğrusu 8’dir.','Çeyrek çıkarılınca kalan yayın uzunluğu (3/4)·2π·8=12π olur; bu, taban çevresine eşittir.'],
 ['2πr=12π’den koni taban yarıçapı r=6 bulunur.','Dik eksen kesitinde h²+6²=8² olduğundan h=√28=2√7’dir. Doğru seçenek C’dir; 8 koninin yüksekliği değil eğik uzunluğudur.'],
 'Çıkarılan çeyrek yayın çevresini taban çevresi almak kalan kâğıdın birleştiğini ters yorumlar; koni 270°’lik dilimden oluşmaktadır.',
 'Yay uzunluğu ve Pisagor','Düzlemde korunmuş yay uzunluğu taban yarıçapını, ana doğru ile yarıçapın dik üçgeni yüksekliği belirler.',
 'Yarıçapı 10 olan daireden yarım daire çıkarılıp kalan kısım koni yapılırsa yüksekliği kaçtır?',['5','5√2','5√3','8','10'],2,'Kalan yay 10π olduğundan taban yarıçapı 5, ana doğru 10’dur. Yükseklik √(100−25)=5√3 olur.','C');
 add(342,'Tam batan silindirin taşırdığı su','Silindir hacmi','AYT-mat',131,
 'Tamamen suya batan bloğun taşırdığı hacmi blok hacmine eşitleyip yarıçap oranını yükseklik oranından ayırmayı ölçer.',
 ['Kap yarıçapı R, yüksekliği H; blok yarıçapı r, yüksekliği H/2’dir.','Kap başta ağzına kadar dolu olduğundan taşan su hacmi πr²H/2, ilk su hacmi πR²H’dir.'],
 ['Taşan oranı (πr²H/2)/(πR²H)=r²/(2R²)=1/32 olarak yazılır.','Buradan R²=16r², pozitif yarıçaplar için R/r=4 bulunur. Doğru seçenek C’dir; karesel oran ile uzunluk oranı ayrı tutulmalıdır.'],
 'Hacimlerin 32 oranını doğrudan yarıçap oranı saymak hem yarım yüksekliği hem de yarıçapın karesini ihmal eder.',
 'Hacim oranı','Aynı tür cisimlerin hacim oranı taban alanı oranı ile yükseklik oranının çarpımıdır; su taşması fiziksel hacim eşitliği sağlar.',
 'Yüksekliği kabın üçte biri olan silindir blok tam batınca dolu kabın suyunun 1/27’si taşıyor. Kap/blok yarıçap oranı kaçtır?',['2','3','4','6','9'],1,'r²/(3R²)=1/27’den R²=9r² ve R/r=3 bulunur.','C');
 all['q-ayt-matematik-342'].note='Kaynak numara hatası: PDF fiziksel109 sol üstte 342 yerine 344 basılmıştır. Sonraki 343 ve sağ sütundaki gerçek344 sırasına göre bu silindir sorusu kanonik342’dir; anahtardaki342-C ile uyumludur.';
 add(343,'Kalem açılmasında eksilen silindir hacmi','Silindir ve koni hacmi','AYT-mat',135,
 'Kalemin toplam uzunluğu değişmeden silindirik bir ucun koniye dönüşmesindeki hacim kaybını başlangıç hacminin yüzde beşine eşitlemeyi ölçer.',
 ['Taban alanı S ve toplam uzunluk L ise başlangıç hacmi S(L−1)+S/3=S(L−2/3)’tür.','Diğer uçtaki birim yükseklikli silindir koni yapılınca S−S/3=2S/3 hacim eksilir.'],
 ['Azalma başlangıç hacminin %5’i olduğundan 2S/3=(1/20)·S(L−2/3) yazılır.','S sadeleşince L−2/3=40/3, dolayısıyla L=14 bulunur. Doğru seçenek B’dir; her iki koni de kalemin aynı toplam uzunluğu içinde kalır.'],
 'Başlangıç kalemini bütünüyle silindir kabul etmek zaten açılmış ilk koninin hacim farkını yok sayar; yüzde hesabının tabanı başlangıçtaki gerçek hacimdir.',
 'Yüzde ve hacim farkı','Aynı tabanlı koni silindirin üçte biri hacmindedir; yerel hacim kaybı bütün kalemin uzunluğunu belirler.',
 'Koni uç yüksekliği 1 olan aynı kalemde ikinci ucu açmak hacmi %10 azaltıyorsa toplam uzunluk kaçtır?',['6','20/3','7','22/3','8'],3,'2S/3=(1/10)S(L−2/3) olduğundan L−2/3=20/3 ve L=22/3’tür.','B');
 add(344,'Basamaklı parçaları yeniden prizma yapma','Prizmanın yüzey alanı','TYT-mat',152,
 'İki özdeş basamaklı parçanın yeniden birleşme şeklinden yeni ayrıtları çıkarıp hacim korunurken yüzey alanının değişebileceğini hesaplamayı ölçer.',
 ['Kesimde 10 birimlik doğrultu özdeşlik nedeniyle iki 5 birimlik bölüme ayrılır; enine genişlik 8 korunur.','Son prizmanın uçlarında kalın kısımlar, ortasında üst üste iki ince kısım vardır; kalınlık 2t, toplam ilk yükseklik 3t=6’dır.'],
 ['t=2, yeni yükseklik 4 bulunur. Parçalar yarım uzunluk ötelenerek birleştiğinden yeni uzunluk 10+5=15’tir.','Yeni ayrıtlar 8,4,15; yüzey alanı 2(8·4+4·15+8·15)=424’tür. Hacim 8·4·15=480 ile korunur; doğru seçenek E’dir.'],
 'Yeni yüksekliği 6/2=3 almak basamaklı kesimin iki yatay düzlemde olduğunu atlar; üst üste gelen iki ince bölüm kalın bölümle eşitlenmelidir.',
 'Hacim korunumu','Yeni boyutların çarpımı ilk 6·8·10 hacmini vermelidir; bu kontrol şeklin yeniden yerleştirilmesindeki hataları yakalar.',
 'Ayrıtları 4,6,12 olan prizmanın yüzey alanı kaçtır?',['192','216','240','264','288'],4,'Yüzey alanı 2(4·6+4·12+6·12)=2(24+48+72)=288’dir.','E');
 add(345,'İç içe iki konide kesit benzerliği','Konide benzerlik ve hacim','AYT-mat',135,
 'Alt koninin içindeki yatay kesit yarıçapını benzerlikten bulup eşit hacim koşuluyla üst koninin yüksekliğini ve yerden tepe uzaklığını ayırmayı ölçer.',
 ['Alt koninin tepesi yerde, tabanı 12 yüksekliktedir. 8 yükseklikteki kesitin yarıçapı taban yarıçapının 8/12=2/3’üdür.','Üst koninin tabanı bu kesitte olduğundan yarıçapı r=2R/3; tabanı yerden 8 birim yukarıdadır.'],
 ['Hacimler eşit: (πR²·12)/3=(π(2R/3)²·h)/3. Buradan h=27 bulunur.','İstenen üst koninin kendi yüksekliği değil, tepesinin yere uzaklığıdır: 8+27=35. Doğru seçenek D’dir.'],
 '27’yi doğrudan sonuç almak üst koninin tabanının zeminde olmadığını unutur; benzerlikte de 12−8 değil, alt tepeden ölçülen 8 kullanılmalıdır.',
 'Benzerlikte hacim','Yatay kesit yarıçapı yüksekliğe doğrusal bağlıdır; hacim eşitliği ise bu yarıçap oranının karesini içerir.',
 'Alt koninin yüksekliği 18, üst koninin tabanı yerden 12 yükseklikte ve hacimler eşitse üst tepenin yerden yüksekliği kaçtır?',['36','81/2','45','105/2','54'],3,'Yarıçap oranı 2/3 olduğundan üst koninin yüksekliği 18·9/4=81/2’dir. Taban yüksekliği eklenince 12+81/2=105/2 bulunur.','D');
 add(346,'Çapraz bantların ortak alanını çıkarma','Kare prizma hacmi','TYT-mat',152,
 'İki bant şeridinin üst yüzde ortak kapladığı birim kareyi bir kez sayıp yüzey alanı koşuluyla kare taban kenarını bulmayı ölçer.',
 ['Taban kenarı a, yükseklik h olsun. Her bant iki yan yüz ile üstte toplam a+2h uzunluğunda ve 1 genişliğindedir.','Bantlar üst yüzde 1×1 karede kesişir; kaplanan birleşim alanı 2a+4h−1=25’tir.'],
 ['a+2h=13 bulunur. Kutunun tüm dış yüzeyi 2a²+4ah=2a(a+2h)=182 olduğundan a=7’dir.','7+2h=13 ile h=3 çıkar. Hacim a²h=49·3=147’dir; doğru seçenek C’dir. Alt yüz bantlanmasa da toplam yüzeye dahildir.'],
 'İki bant alanını doğrudan toplamak üstteki kesişimi iki kez sayar; 25 kaplanan yüzeyin birleşim alanıdır.',
 'Kümelerde birleşim alanı','İki şeridin toplamından ortak kısım çıkarılır; elde edilen doğrusal ifade prizmanın yüzey formülünü sadeleştirir.',
 'Kare tabanlı kutuda aynı iki birim genişlikli bant 21 alan kaplıyor ve toplam yüzey 110 ise hacim kaçtır?',['50','60','75','90','100'],2,'2a+4h−1=21’den a+2h=11; 2a·11=110’dan a=5,h=3 olur. Hacim 75’tir.','C');
 add(347,'Küpten tam yükseklikte parça çıkarma','Katı cisimde yüzey değişimi','TYT-mat',154,
 'Köşe bölgesinden tam yükseklikte dik prizma çıkarılırken kaybolan ve yeni açılan yan yüzlerin birbirini götürdüğünü fark ederek boyutları bulmayı ölçer.',
 ['Küp ayrıtı c, çıkarılan taban kenarları a,b olsun. Çıkarılan parça a×b×c boyutundadır.','Dışta kaybolan ac ve bc yan alanları, içeride açılan aynı alanlarla dengelenir; yüzey azalışı yalnız 2ab=40’tır.'],
 ['ab=20 ve çıkarılan hacim abc=180 olduğundan c=9 bulunur. a,b pozitif tam sayı ve 9’dan küçük olmalıdır.','20’nin bu koşulu sağlayan çarpanları 4 ve 5’tir. Parça yüzeyi 2(4·5+4·9+5·9)=202’dir; doğru seçenek A’dır.'],
 'Yüzey azalmasını çıkarılan prizmanın tüm yüzeyi sanmak yeni iç yüzlerin ortaya çıktığını yok sayar; yalnız üst ve alt taban kaybı net değişir.',
 'Alanların iptali','Çıkarmayla silinen dış yan yüzler eşit büyüklükte iç yüzlere dönüşür; net alan değişimi taban çarpımını verir.',
 'Aynı kesimde yüzey 24, hacim 96 azalıyor ve çıkarılan taban kenarları 3 ile 4 ise çıkarılan parçanın yüzeyi kaçtır?',['112','120','128','136','144'],3,'ab=12, c=96/12=8’dir. Yüzey 2(12+24+32)=136 olur.','A');
 add(348,'Eş hacimli yarım silindir ve yarım küre','Silindir ve küre','AYT-mat',137,
 'Eşit hacimden yarım silindirin boyunu yarıçap cinsinden bulup zemin hariç yüzeyde uç kapakları dahil etmeyi ölçer.',
 ['Yarım silindir hacmi πr²h/2, yarım küre hacmi 2πr³/3’tür. Eşitlik h=4r/3 verir.','Yarım silindirin zemin dışı alanı eğri örtü πrh ile iki yarım daire kapağın toplamı πr²’den oluşur.'],
 ['Silindir alanı πr(4r/3)+πr²=7πr²/3 bulunur.','Yarım kürenin zemini hariç yalnız eğri alanı 2πr²’dir. Oran (7πr²/3)/(2πr²)=7/6 olur; doğru seçenek D’dir.'],
 'Yarım silindirin iki yarım daire ucunu dışlamak bina tamamen kapalıyken duvar alanlarını kaybettirir; dışlanan yalnız zemindeki dikdörtgendir.',
 'Hacimden boyut oranı','Ortak yarıçap hacim eşitliğinde sadeleşir ve boy/yarıçap oranını sabitler; yüzey oranı da ölçekten bağımsız olur.',
 'Yarıçapı 3 olan yarım silindir, aynı yarıçaplı yarım küreyle eş hacimliyse zemin hariç alanı kaçtır?',['12π','15π','18π','21π','24π'],3,'Eşit hacim h=4 verir. Eğri örtü 12π, iki yarım daire uç toplamı 9π; dış alan 21π’dir.','D');
 add(349,'Masaldaki kapların eşit hacminden yarıçap','Silindir hacim oranı','AYT-mat',131,
 'Görsel içindeki masal metninden iki silindir kabın yarıçap ve yüksekliklerini seçip eşit hacmin yarıçaplarda karekök oranı gerektirdiğini kullanmayı ölçer.',
 ['Tilkinin kabı yarıçapı 15 cm, yüksekliği 1 cm olan silindirdir; hacmi 225π cm³’tür.','Leyleğin kabının yüksekliği 36 cm, bilinmeyen yarıçapı r’dir; hacmi 36πr²’dir.'],
 ['Hacimler eşit olduğundan 36πr²=225π, buradan r²=225/36=25/4 bulunur.','Yarıçap pozitif olduğundan r=5/2=2,5 cm alınır. Doğru seçenek C’dir; masalın gaga ve ağız ayrıntıları sayısal hacim koşuluna ek kısıt getirmez.'],
 'Yükseklik 36 katına çıkınca yarıçapı 36’ya bölmek kesit alanının yarıçapın karesiyle değiştiğini unutur; yarıçap 6 kat küçülür.',
 'Ters orantı ve karekök','Sabit silindir hacminde r² ile h ters orantılıdır; yükseklik oranının karekökü yarıçap oranını verir.',
 'Yarıçapı 12, yüksekliği 2 olan silindirle aynı hacimli ikinci silindirin yüksekliği 18 ise yarıçapı kaçtır?',['2','3','4','6','8'],2,'144·2=r²·18’den r²=16 çıkar. Pozitif yarıçap 4’tür.','C');
})();
